rows[1005660]={title={{37,1435474461}," ⁇ 스  ⁇ 스  ⁇ 스  ⁇ 스  ⁇ 스"},description={{221,642653079},"안녕히 히어로!\010최근 우리는 공급 부족의 한가운데에 있었고, 20  ⁇ 레클 바디지, 끝을 이루기 위해서"},objectives={{30,156856706},"40  ⁇ 클로트 바인더를 수집하세요."}}
rows[1005661]={title={{43,542049798}," ⁇ 을  ⁇ : 무거운  ⁇ 레 ⁇  바  ⁇ "},description={{227,276576718},"안녕히 히어로!\010최근 우리는 공급 부족의 한가운데에 있었고, 10  ⁇ 레클로트 가죽으로 끝을 맺기 위해서"},objectives={{36,1459687860},"20 무거운 룬클로트 붕대를 수집하십시오."}}
rows[1005664]={title={{25,643990632},"희미 한 선: 원료 의  ⁇ 어"},description={{163,884891773},"안녕히 히어로!\010최근 우리는 공급 부족의 한가운데에 있었고, 당신의 수준의 공예가 우리를 이 일상에서 끌어낼 수 있기를 바랬습니다. "},objectives={{25,718079843},"10 원료의 삼촌고래를 수집합니다."}}
rows[1005674]={title={{31,1773235999},"진정한 공예:  ⁇ 옷 의 옷"},description={{283,1041639818},"진정한 공예는 신화적인 기적을 창조할 수 있는 사람이다.\010\010당신 같은 진정한 공예만이 이 악의 상황을 벗어날 수 있습니다.\010\010수집 2 펠클로스 갑옷 세트, 그리고 귀여운 보상을 위해 전화보드에 돌려주면 모든 문제가 해결될 겁니다."},objectives={{24,95419838},"1 펠클로트 로브를 수집하십시오."}}
rows[1005689]={title={{29,815003036},"진정한 공예: 바르"},description={{296,2128058190},"진정한 공예는 신화적인 기적을 창조할 수 있는 사람이다.\010\010당신 같은 진정한 공예만이 이 악의 상황을 벗어날 수 있습니다.\010\01020 펠 아이언 바스와 20 애덤아티트 바를 수집하고, 좋은 보상을 위해 전화보드에 배달하면, 이것은 당신의 모든 문제를 덮어줄 것입니다."},objectives={{25,1603881011},"20 펠 아이언 바를 수집합니다."}}
rows[1007453]={title={{45,261723384},"부정적 의 의도는: 가죽 노동자 의  ⁇ "},description={{395,60498475},"동물 보호 단체들은 우리가 피부를 얻는 방법에 대해 \"걱정\"하고 있습니다.$b$b영웅들의 도움이 필요해요. 그것은 소수 일일 수도 있고, 동물권 단체들이 피부를 얻는 방법에 대해 괴롭히고 있지만, 지금은 중요하지 않습니다. 중요한 것은,$b$b수집 1 네 도움에 대해 천혜의 보상을 받을 거야"},objectives={{33,321988263},"1 가죽 노동자 사트케이크 수집"}}
rows[1007496]={title={{29,450008440},"자연 혼합물: 아데프트 에릭시어"},description={{460,752072385},"우리 최신 혼합물에 대한 약이 부족해$b$b우리 도움 에 필요 합니다. 영웅 들 이요. 그것은 하찮은 일 일 일일 수도 있지만, 우리 최신 혼합물 에 대한 허브가 부족했습니다! 우리는 전혀 추가 된 맛 없이 모든 자연 허브 혼합물을 만듭니다! 그러나, 우리의 최신 허브 혼합물은 빠르게 판매되고 있는 것 같습니다. 그리고 우리는 더 많은 것을 만들기 위해 공급이 부족합니다! 당신은 우리에게 용의를 할 수 있다고 생각합니까?$b$b수집 4 아데프트의 엘리시어, 당연히 당신의 도움에 대해 대부적으로 보상받을 것입니다."},objectives={{24,933495802},"4 아데프트 에릭시르"}}
rows[1007597]={title={{39,56339629},"자연적 혼합물: 가장 강력한 에릭시어"},description={{470,745123095},"새로 섞을 약초가 떨어진 모양이군요…$b$b용사님들의 도움이 필요합니다. 허드렛일 같아 보여도 새로 만든 혼합물에 들어갈 약초가 떨어졌습니다! 저희는 향을 더하지 않은 순수한 약초만 섞습니다. 그런데 새 혼합물이 날개 돋친 듯 팔리는 바람에 재료가 모자라요. 부탁을 하나 들어 주시겠습니까?$b$b일급 힘의 비약 4개를 모아 주십시오. 도와 주시면 후하게 보상하겠습니다, 용사님."},objectives={{34,922922782},"4 주요 강도의 엘리시르"}}
rows[1038797]={title={{61,1057297205},"공급량: 매혹적인 브레이저의 스크롤 - 더 적은 힘"},description={{163,884891773},"안녕히 히어로!\010최근 우리는 공급 부족의 한가운데에 있었고, 당신의 수준의 공예가 우리를 이 일상에서 끌어낼 수 있기를 바랬습니다. "},objectives={{53,1004159279},"6  ⁇ 마자  ⁇ 마자 - 더 적은 힘"}}
rows[1038884]={title={{62,2019022830},"공급량: 마법의 무기의 서적 - 강력한 지능"},description={{163,884891773},"안녕히 히어로!\010최근 우리는 공급 부족의 한가운데에 있었고, 당신의 수준의 공예가 우리를 이 일상에서 끌어낼 수 있기를 바랬습니다. "},objectives={{54,1333802218},"1 매혹적인 무기의 서적 - 강력한 지능"}}
rows[1660000]={title={{8,81619181},"책벌레"},description={{540,873348385},"<한 여인이 몹시 동요한 표정으로 당신을 맞이합니다. 눈에 분노와 걱정이 뒤섞여 있습니다.>$B$B미안해요. 소란을 피울 생각은 없었는데… 그 빌어먹을 동생 녀석은 늘 책에만 파묻혀 있다니까요! 여기서 한참을 목이 터져라 불렀는데 감감무소식이에요. 경비병들도 한 번만 더 수도원의 평화를 어지럽히면 가만두지 않겠다고 했어요.$B$B안에 들어가서, 필요하다면 귀라도 잡고 그 녀석을 끌고 나와 주겠어요? 어머니가 임종을 앞두고 계셔요. 마지막 인사라도 하게 하려고 먼 길을 와서 찾는데, 저 철없는 녀석은 보이질 않네요."},objectives={{53,1005567762},"비앙카 스파다의 남동생인 신학생 모로이와 대화해야 합니다."},completion={{266,598390951},"여동생이 보내신 건?$b$b이미 그녀에게 이 때가 좋지 않다고 말했지만 솔직히, 그녀와 대결할 때 좋은 때가 없습니다.$b$b어쨌든, 내가 완전히 빠져들게 된 발견 중이야."}}
rows[1660001]={title={{18,451992844},"지식은 타락을 부른다"},description={{626,25084169},"자, 한번 보십시오.$B$B<모로이가 시선을 빼앗긴 책을 가리킵니다. 읽는 이를 닮아 얇고 낡은 필사본입니다.>$B$B도서관에서 우연히 발견했습니다. 수도원의 장부에는 없는 책입니다. 오래전 이단 혐의를 받은 어느 수녀원장의 기록 같군요. 마음이 급한 나머지 낱장을 몇 장 잃어버렸습니다. 다시 맞춰 보고 있지만 아직 빠진 부분이 있습니다.$B$B수도원 안을 둘러보고 빠진 낱장을 찾아 주시겠습니까? 이건 금서입니다. 제가 기웃거린 게 들통나면 집으로 쫓겨나겠죠. 하필 누나가 있는 집으로요.$B$B부디 저를 좀 살려 주십시오."},objectives={{95,1199504769},"수도원 곳곳에 흩어진 모로이의 미분류 필사본 낱장을 찾아야 합니다."},completion={{377,558228743},"어디, 무엇을 가져오셨습니까?$B$B<모로이가 가져온 낱장들을 열심히 살펴봅니다.>$B$B이제 빈 곳이 좀 채워졌군요. 이단 혐의를 받은 수녀원장은 이단심문을 받고 파문당했습니다. 교단에서 그 일의 기록을 모조리 지우려 한 것도 이해가 됩니다. 이 책을 태우는 걸 잊었다니 거의 기적이군요.$B$B대체 무슨 일을 했기에 그런 처벌을 받았는지 궁금해지지 않습니까?"},progress={{25,898249287},"낱장을 찾으셨습니까?"}}
rows[1660002]={title={{23,1043545599},"북녘골의 폐허"},description={{338,611279799},"수녀원장이 심문을 받았던 지하감옥에 가 보면 실마리를 찾을지도 모릅니다…$B$B책에 따르면 지금은 버려진 북녘골 마을에 이단심문 지하감옥으로 들어가는 비밀 입구가 있었다고 합니다.$B$B지도에 표시해 드리죠. 하지만 조심하십시오. 몇 년이나 아무도 발을 들이지 않은 곳입니다. 그 폐허에 무슨 벌레 같은 것들이 둥지를 틀었을지 상상도 하기 싫군요."},objectives={{63,1406030625},"비밀 이단심문 지하감옥으로 이어지는 지하실 입구를 찾아야 합니다."},completion={{171,2132282233},"길이 닫혀, 필사자$b$b감옥은 죽은 자들의 집이고 죽은 사람들은 그렇게 유지하죠.$b$b감옥에서 살면서도, 죽음에서 죽는 죄수들... 우리 모두는 그녀의 저주의 희생자입니다.$b$b길이 닫혀 있어"},progress={{18,1424227650},"길은 닫혀 있느니라…"}}
rows[1660003]={title={{19,1283176794},"저주받은 수녀회"},description={{430,1946837976},"길은 닫혀 있느니라. 수녀원장은 자신을 심판한 자들에게 저주를 내려, 안식을 잃고 떠도는 혼령으로 묶어 두었다.$B$B죽은 이들은 아직도 그 힘에 매여 있다. 그 여인에게서 빼앗았던 존엄과 소지품이 이제는 그들의 족쇄가 되었지. 짧은 기도와 진심 어린 간청이면 충분할 터인데…$B$B누군가 이 감옥 곳곳에 흩어진 수녀원장의 유품을 정화하기 전까지 그들은 안식을 얻지 못하리라.$B$B하지만 죽은 자들이 유품을 굳게 지킨다. 그리하여 길은 여전히 닫혀 있느니라."},objectives={{98,1549995254},"비밀 이단심문 지하감옥 곳곳에 흩어진 전 수녀원장의 유품을 정화해야 합니다."},completion={{341,370340360},"저주가...$b$b길이 열렸어요. 나는 그것을 느낄 수 있습니다. 따뜻한 빛은 다른 곳으로 내 영혼을 불러.$b$b<사녀는 더 깨어 있고, 이전보다 더 의식적으로 보인다>$b$b한 번은 내가 알마 수녀, 제사장 북녘골 아비$b$b지식을 찾아 왔어 처음은 아니지만 마지막이 될 거란 걸 믿어요$b$b잘 해, 시티스에 대해 얘기해볼게요."},progress={{67,1444980005},"아직 길은 닫혀 있느니라, 필멸자여…$B$B영혼을 덮은 밤이 영원히 걷히지 않는구나."}}
rows[1660004]={title={{27,356572177},"광기로 이끄는 말"},description={{552,1865810328},"시티스는… 폭풍과도 같은 사람이었어요. 그의 가르침은 정통에서 벗어났고, 위험하기까지 했습니다. 수많은 학생이 그로 인해 교단을 떠났지요.$B$B이단심문 법정에 증인으로 소환되었을 때, 저는 그에게 불리한 증언을 하기로 했습니다.$B$B시티스가 폭포 위의 오래된 저택에서 가장 가까운 추종자들과 비밀리에 모인다는 걸 알고 있었습니다. 그 모임에서 시티스는 빛과 생명, 죽음, 그리고…$B$B어둠의 본질에 대해 말했습니다.$B$B그 이단의 흔적이 아직도 그 땅에 남아 있습니다. 그곳에 가신다면 조심하세요. 추종자가 적지 않았고, 이단심문관들은 그들을 모두 잡지 못했습니다…"},objectives={{114,429477004},"폭포 위로 이어지는 숨은 길을 찾아 전 북녘골 수녀원장의 죄와 마주해야 합니다."},completion={"<Moroi listens to your account intently.>$b$bThey say the pen is mightier than the sword, and Sitis... fitting name. It means \"thirst.\" From what you've told me, she was a woman thirsty for truth and knowledge.$b$bI hardly think that's a sin.$b$bHere's my plan, $N: I'll go with my sister, say my goodbyes to my mother, and on my way back to the abbey, I'll stop by that place you spoke of, where Sitis held her most daring gatherings.$b$b\"There is no darkness but ignorance.\" I thank you for the warning, but my mind won't rest until I uncover the truth... no matter the risks you've mentioned.","<모로이가 당신의 이야기를 주의 깊게 듣습니다.>$B$B펜은 칼보다 강하다는 말이 있죠. 시티스라… 어울리는 이름입니다. 갈증이라는 뜻이지요. 말씀을 들어 보니 진리와 지식에 목말랐던 사람이군요.$B$B그걸 죄라고 할 수 있을지 모르겠습니다.$B$B이렇게 하겠습니다, $N 님. 누나와 함께 돌아가 어머니께 작별 인사를 드리겠습니다. 수도원으로 오는 길에는 당신이 말씀하신 곳, 시티스가 가장 대담한 모임을 열었던 그곳에 들르죠.$B$B“무지만이 어둠이다.” 경고는 고맙지만, 말씀하신 위험을 무릅쓰더라도 진실을 밝혀내기 전에는 마음을 놓을 수 없을 것 같습니다."},progress={{17,1324455700},"알아낸 것이 있습니까?"}}
rows[1660005]={title={{27,1206845228},"물길을 타고 온 위협"},description={{569,2055999309},"도움이… 필요합니다.$B$B<병사는 고통에 겨워 숨이 끊길 듯한 목소리로 말합니다. 얼굴을 찡그릴 때마다 상처가 다시 벌어지는 듯합니다.>$B$B멀록 마을을 찾아 위협을 막으라는 명령을 받았습니다. 보시다시피 오는 길이 순탄치 않았습니다. 설상가상으로 상류까지 가는 길은 저 탑을 통과하는 것뿐입니다.$B$B<그는 폐허가 된 탑을 향해 힘겹게 고개를 끄덕입니다.>$B$B하지만 당신이라면… 제가 못한 일을 해낼지도 모르겠습니다.$B$B탑을 점거한 데피아즈단을 처리하고 폭포 위 멀록의 수를 줄여 주십시오. 저뿐 아니라 온 왕국이 감사할 겁니다."},objectives={{133,390648828},"폐허가 된 탑에 숨은 데피아즈단을 무찌르고 밧줄 다리 너머 폭포 위에 있는 그늘샘 멀록의 수를 줄여야 합니다."},completion={{302,1478894506},"넌 해냈어...$b$b저는 너무 자랑스럽게 입고 있는 유니폼을 부끄럽게 여기고 군대를 제외한 누군가에게 회부해야 했습니다.$b$b내가 해야 할 일이었지, 하지만, 보시다시피, 나는 아비티로 돌아가는 힘이 없다.$b$b스톰윈드 감사해야 합니다. 수호자... 나도 그렇죠"},progress={{69,1818092441},"제 걱정은 마십시오. 따라갈 수는 없지만, 이 자리는 지킬 수 있습니다."}}
rows[1660006]={title={{17,1644456814},"바람 에 나오는 연기가"},description={{724,101705318},"아, 여행자군요! 차림새를 보니 멀리서 오셨군요.$b$b가까이 와서 보세요. 갓 태어난 제 아이가 어떤 치유사도 고치지 못한 병을 앓고 있어요. 시간이 얼마 남지 않았죠. 하지만 아이의 형은 받아들이려 하지 않아요.$b$b어디선가 온갖 병을 고친다고 주장하는 ‘교단’의 소문을 들었나 봅니다. 그렐빈은 물에 빠진 사람이 나뭇조각을 붙들듯 그 희망을 붙잡고 그들을 찾아 떠났습니다.$b$b벌써 이 주 전입니다. 아직 돌아오지 않았고, 아이가 떠난 방향에서 불길한 검은 연기가 바람에 실려 옵니다. 끔찍한 일이 생겼을까 두려워요.$b$b제발… 아이가 간 길을 따라가 제게 데려다 주세요. 신들은 제게 아들 하나를 내놓으라 하셨습니다. 둘 다 잃을 수는 없어요."},objectives={{92,1590210540},"그롤다의 아들 그렐빈의 발자취를 따라가서 연기의 원천을 조사해 보세요."},completion={{301,380690990},"<고블린은 로켓의 잔해에서 최대한 뛰어내렸고 그의 힘이 없어지고 마지막 숨은 발진한 목에서 빠져나갔다.>$B$B<공격으로 다리가 피가 흐르는 덩어리로 줄어들었지만, 여전히  ⁇ 은 바지를  ⁇ 고 있는 종이 한 잔의 덩어리가  ⁇ 어져 있습니다.>"},progress={{53,229864471},"<고블린은 의심의 여지가 없는 채로 돌이킬 수 없는 죽음이다>"}}
rows[1660007]={title={{16,1495612716},"약속 의 길"},description={{411,1709848122},"<신체를 약탈하기 전에, 당신은 괴물이 그의 주머니에 있는 서류를 놓치지 않을 것이라고 생각합니다.>$b$b<그들을  ⁇ 어 보면, 그 괴물은 콜드리지 산맥에서 신비한 무지론자들을 찾아 보내진 팀의 일원이라는 것을 알 수 있습니다. 그 그룹은 그롤드하의 아들 그렐빈이 찾고 있었습니다.>$b$b<신문들 사이에 산을 올라가는 길을 표시하는 지도가 있습니다."},objectives={{73,105556919},"신비한 집단의 위치를 찾기 위해 산 경로를 따라가세요."},completion={{304,1661028633},"내  ⁇ 에 의해... 난 거의 총을 쏘아 넣었어$B$B여기 앉으세요. <왜란은 방울 쪽으로 따뜻하게 움직입니다. 이 얼어붙은 황무지에서 찾을 수 있는 유일한 따뜻함입니다.>$B$B그롤더의 소년을 찾고 있어요? 저 가난한 여자."},progress={{31,1343806991},"그리고 당신은 누구야?"}}
rows[1660008]={title={{18,1035450347},"적절 한 외모"},description={{638,1405607507},"앞쪽은 라디언스 타운의 문입니다. 그 종파의 거시입니다. 그들은 스스로를 라디언스라고 부르고 있습니다.$b$b그들은 파괴된 곤메리건과 같은 방사능으로 목욕하면 어떤 종류의 계시가 주어질 것이라고 믿거나,$b$b그들은 위험합니다. 이단자와 반란자. 그들의 지도자는 자신을 왕으로 즉위했습니다.$b$b이제 여기 왔으니... 계획이 떠오르네.$b$b길을 따라가, 앞으로의 숲을 탐험해, 그리고 그 열렬한 사람들을 몇 개 깎아내라."},objectives={{106,1270254914},"반지방 팬티들을 죽이고 그들의 갑옷을 수집하고 아라터로르에게 넘겨주면 그가 위장을 만들 수 있을 거야"},completion={{130,1820425105},"그래, 이럴 수 있어...$B$B네 크기가 아니지, 하지만 나보다 잘 어울릴 거야 내 코만으로는 그렇게 작은 헬멧에 들어갈 수 없어"},progress={{70,1795917733},"산의 추위를 살아남기 위해 좋은 싸움이 없다!"}}
rows[1660009]={title={{19,822704085},"그의 빛나는 대왕"},description={{524,741441478},"난 방사선과 너무 많은 충돌을 해 왔어, 그들은 날 갑자기 발견할거야. 하지만... 넌 새로운 사람이야.$b$b이 위장도 지나갈 것 같아 준비되면 알려줘서 도와줄게$b$b한 번 위장되면 머리를 낮추고, 관심을 끌지 않고 멀리 떨어진 마을을 건너서, 그들의 이른바 왕을 찾아라.$b$b만약 이것이 그들 중 하나라면, 당신은 그롤드아의 아들을 정신이 나지 않도록 도울 수 있을지도 모릅니다."},objectives={{129,700101679},"마스크를 입을 준비가 되면 아라서러에게 말해 라디언스 타운에 침투하고"},completion={{596,1474510573},"네가 돌아왔어, 내가 말해보고 싶었지만, 널 찾을 줄 몰랐는데, 그레빈은 네가 떠난 지 얼마 지나지 않아 돌아왔어, 그리고 네가 믿지 않을거야.$B$B아직은 그 아이의 건강이 좋아졌다고 말할 수는 없지만, 위험은 그만한 가치가 있었습니다.$B$B그레빈이 여기 없어서 부끄럽지만, 그 아들...$B$B그는 다시 교회로 돌아갔고 그 학자들 사이에서 좋은 친구를 얻었다고 말했습니다. 아마도 그가 돌아왔을 때 당신은 여전히 안빌마르에 있다면, 당신은 직접 그를 만날 수 있을 것입니다."},progress={{85,770015295},"아인빌마르로 돌아갔는데 내 아들이 없었을 때..."}}
rows[1660010]={title={{21,1066047676},"방사선 을 해독"},description={{445,503786578},"만약 당신이 광명시로 몰래 들어가면... 당신의 도움이 필요할 수 있는 일이 있습니다.$b$b저는 방사능이 어떻게 작용하는지 이해하려고 노력했습니다. 그 효과에 대항하는 방법을 찾고 있습니다. 그 목적을 위해...$b$b<레드나가 보여준 건 총과 약간 닮은 기구입니다>$b$b방사성  ⁇ 을 죽이고 그 다음 이 미를 끄는 건  ⁇ 이  ⁇ 의 본질을  ⁇ 어내게 될 것이고, 운이 좋으면,"},objectives={{113,1145918214},"방사성  ⁇ 을 죽이고, 유성균을 추출하기 위해"},completion={{484,1976904832},"정말 재밌어, 솔직히, 당신 손에 폭발하지 않을 거라고 확신하지 못했어요.$B$B<레드나는 발톱을 벗겨진 손가락을 이용해 발톱에 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 긁어 뜯어 긁어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 뜯어 $B$B여기 있는 원자력 도구로 샘플을 분석하는 데 시간이 걸릴 겁니다. 하지만 이 문제에 대해 알아낼 겁니다. 그리고 그렇게 되면, 저는 톱니 톱니를 들고 더 깊이 파헤쳐볼 겁니다.$B$B치료법을 찾아볼게요"},progress={{91,2058904147},"이 유동물 샘플을 가지고 난 방사능의 미스터리를 풀어나갈 한 걸음 더 가까워질 거야"}}
rows[1660011]={title={{18,676322393},"대중 을 젖게 하는 것"},description={{579,601609087},"여기 새로 왔어?$b$b미안해, 내가 널 만났을지도 모르지만 내 기억은...  ⁇ 이  ⁇ 이  ⁇ 이  ⁇ 고  ⁇ 이  ⁇ 고  ⁇ 고  ⁇ 고$b$b친구나 낯선 사람, 당신의 도움이 필요해. <라후드는 죄책감한 작은 웃음을 질식시키고, 분명히 부끄러워한다>$b$b<그놈은  ⁇ 을  ⁇ 고  ⁇ 을  ⁇ 고  ⁇ 을  ⁇ 고 마치 살아있는 케이블을 잡은 것처럼 떨고 있다.>$b$b이 마을 사람들한테 복사선만 뿌려야지 주 주당 복용량을 줘서"},objectives={{73,1642408032},"방사선 스프레이어를 이용해 라디아빌 마을 사람들을 방사선으로 마비시켜라"},completion={{277,1705348178},"<성경이 더 심해졌어요. 그놈은 한 눈을 거의 열지 못해요.>$B$B끝냈어?$B$B입에서  ⁇ 줄이 걸려 있어, 당신 없는 동안 오토가  ⁇ 어$B$B내가 이 팀에 합류한 이후로 병은 심화됐어"},progress={{18,2071433810},"다 끝났어?"}}
rows[1660012]={title={{16,1278002993},"카리온 도로"},description={{584,1875820323},"<엘프가 정중히 고개를 숙여 인사한다.>$b$b실례합니다. 먼 길을 왔는데 여기선 아무도 도와줄 생각이 없어 보입니다. 혹시… 도와주시겠습니까?$b$b제 누이 엘리드나를 찾고 있습니다. 반년쯤 전, 비밀 드루이드 결사에 초대받더니 작별 인사도 없이 떠났습니다. 그 뒤로 돌아오지 않았지요.$b$b누이의 발자취를 따라 이곳 그늘협곡까지 왔습니다. 하지만 저는 평범한 상인이에요. 칼도 제대로 쥘 줄 모릅니다! 드루이드들이 숨은 숲으로 향하는 길은 경계가 삼엄하고 위험합니다.$b$b제 대신 그 길을 가서 누이가 살아 있는지 확인해 주시겠습니까?"},objectives={{47,1728127035},"캐리온 경로를 따라가며 보호자들을 물리치"},completion={{127,437895450},"그만해$b$b내가 널 느낄 수 있어 네가 거기 있다는 걸 알아 우리 중 한 사람이 아니라는 걸 알아$b$b어떤 일이 너한테 여우종자 귀리까지 데려왔어?"},progress={{170,552111407},"<엘프가 노란색,  ⁇ 한 치아를 보여줘서 충분히 경고해줘요>$b$b캐리온 경로를 살아남은 사람들만 여우들의 종들의 둥지에 환영받습니다."}}
rows[1660013]={title={{29,1174645483},"결코 돌아오지 않은 자매"},description={{395,1597345960},"그래서... 당신은 당신의 의지로 여기 온 것이 아니라... 자부심을 가지고 있습니다.$b$b저는 맹세를 하고 있습니다. 우리 회원들을 위해 말할 수 없습니다. 당신은 우리 여부, 우리의 선생님, 우리의 가이드, 레이디 에그야 앞에서 간청해야 합니다. 그녀는 당신과 무엇을 해야할지 결정하고,$b$b안쪽에서 레이디 에그야를 찾을 수 있어요"},objectives={{101,1056290037},"여신 에그야와 이야기해, 여우귀 숭배의 지도자, 그리고 타릴의 여동생 엘리드나에게 무슨 일이 일어났는지 물어봐."},completion={{360,1227293702},"성찬은 모든 초신자에게는 가장 신성한 순간입니다. 엘리드나는 자신의 목숨을 걸고, 여우의 드루이드로서 서야 할 권리를 위해 싸워야 합니다.$b$b하지만 아직 준비가 필요해 동생을 위해 애를 품고..."},progress={{91,200636622},"에그야의 눈의 빈 점들은 어떤 칼보다 더 깊게 자르는 시선을 가지고 당신을 쳐다보고 있습니다."}}
rows[1660014]={title={{21,1139420510},"좋은 육류 를 찾는 것"},description={{521,1776995453},"대우조각은 변동적이지만, 그는  ⁇ 고 간구하는 사람들을 기억합니다. 적절한 희생으로, 아마도 그는 엘리드나에게 화교를 할 때 친절하게 보일 것입니다.$b$b<아기야 여인의 왜곡한 미소는 정반대의 것을 암시한다.>$b$b우리가 달빛 골반이라고 부르는 덩굴에 들어가서 그 잔잔한 홀 안에서 부패하는 시체에서 좋은 고기를 5 조각으로 가져오세요.$b$b조심하세요, 우리는 그들의 몸을 발효하도록 하죠, 그들의 맛이 더 잘 대우조류의 콧물처럼 느껴질 수 있도록요. 그리고 부패는, 여러분도 잘 알고 있듯이, 모든 종류의 곤충을 끌어들이고 있습니다."},objectives={{85,2017382509},"독수리 교단의 둥지 안에 있는 달빛 납골당에서 질 좋은 고기 다섯 덩이를 모으십시오."},completion={{251,1006549565},"맛도 거의 느껴요, 5개를 가져왔어요?$b$b<아예아는 혀를 천천히 그리고 비단하게 입술로  ⁇ 니다. 검은 발자국과 점액이 흐르는 것 같습니다.>$b$b대우조선수... 오늘 저녁에 파티를 할 거야"},progress={{98,2102733375},"시간이 짧고 큰 여우가 불안해져 있습니다."}}
rows[1660015]={title={{29,315841947},"육체를 변화 시키고"},description={{491,1848640272},"마지막 한 걸음 남았어요.$b$b네가 모은 고기는 부패로 drips, 하지만 그것은 너무 건조합니다. 대 여우는 그의 희생물을 습하게 좋아, 그래서 그들은 그의 잔인한 콧물 젖게.$b$b이 고기를 우리 달의 부산으로 가져가라. 알루네의 얼굴은 많은 사람들 중 하나일 뿐이야.$b$b달의 물 속에 있는 육체를 축복하고 그 깊은 곳에서 떠오르는 그림자를 죽여라"},objectives={{71,59498890},"모은 육체를 달수리로 가져가서 물 속에 거룩하게 하라"},completion={{128,1972740490},"부패한 육신... 거룩해졌어.$b$b시간이 왔어 엘리드나 윈스트록의 성찬이 시작됩니다"},progress={{79,2041356157},"동정식은 시작될 예정이야. 당신은 아직 세례의 육체를 거룩하게 하지 않았어?"}}
rows[1660016]={title={{17,1719368559},"공동식"},description={{356,2120208746},"여기$b$b<길가엔은 당신의 손을 만지고 성스러운 육체를 당신의 손바닥에 다시 압축합니다.>$b$b ⁇ 에 넣어두라 엘리드나가 큰 여우를 기쁘게 하기 위해 모은 다른 희생물과 함께$b$b우리들 중 한 명의 동참을 하는 것이 영광입니다. 엘리드나는 당신을 만나기 위해 기다릴 수 없습니다."},objectives={{115,386562606},"성스러운 육체를 대우조류의 둥지에 넣고 엘리드나에게 동식절을 완수하는 데 도움을 주십시오."},completion={{404,340153299},"위대한 여우가 기뻐하고$b$b엘리드나한테 미안하다고 말하지 마.$b$b아니면 승리하고 우리 중 한 명처럼 일어설 수도 있고 아니면 실패할 수도 있고, 달빛 골반에 부패할 수도 있습니다.$b$b엘리드나에게 기회가 있었다. 당신은 단순히 더 강하다는 것을 증명했습니다. 자신의  ⁇ 공연을 성공으로 간주하십시오. 이 순간부터, 당신은 선택할 수 있습니다: 우리와 함께... 또는 떠나."}}
rows[1660017]={title={{17,1192932758},"꽃잎 의 흔적"},description={{621,237331317},"방문자... 우리는 우리 가운데 낯선 사람들을 환영하는 경우는 거의 없습니다. 그리고 좋은 이유 때문에: 우리의 관습은 수천 년 전에 금지되었습니다.$b$b가끔은 제가 생각하기에, 사실, 레이디 에이지야가 풍자만 떨리는 일을 할 준비가 되어 있습니다.$b$b그들을 구해줘, 대둥이로 가서 사체를 찾아라, 너로 나의 힘을 통한$b$b이 꽃의 왕관을 매료시켰는데 그 향기가... 저항할 수 없을 것입니다.$b$b여기 데려와 나머지는 내가 처리해"},objectives={{135,1391580563},"채널 엘디아 ⁇ 은 대구에 있는 신생아들을 돌고래로 바꾸어  ⁇ 을 엘디아로 데려다줍니다."},completion={{289,2045361670},"<엘프가 숨을 쉬고 꽃의 향을 들린다>$b$b- 그들은 따라갔어$b$b대우조류는 많은 교훈을 가르쳐 주지만, 그 콧수염의 잔인함에 대한 그런 부드러운 생명을 희생하는 것은...$b$b무슨 일이든, 난 이 아이들을 안전하게 지켜줄게"},progress={{50,2109920886},"시간대로 도착했나요?"}}
rows[1660018]={title={{14,176049389},"타락 한 사람"},description={{581,1836089836},"죽은 자들의 영들은 불안해하며 꿈과 환상으로 우리를 괴롭히고 있습니다. 이미 우리 중 많은 사람들을 깨뜨렸습니다.$b$b이봐요$b$b<에스그라모르는 당신의 손에 그 작은 크기가 시사하는 것보다 훨씬 무거운 돌을 넣습니다.>$b$b그것은 보호자입니다. 깨진, 고생된 사람들에게 가서, 그들의 불안한 정신의 조각을 끌어내는 데 돌의 힘을 사용하십시오. 당신이 할 수있는 것을 수집하고 Zev Goro의 마녀에게 가져 오십시오. 그녀는 무서운 힘과 깊은 지혜의 마녀입니다.$b$b그녀가 해야 할 일을 알게 될 거라고 믿습니다."},objectives={{152,635779873},"비명기 돌을 이용해 불안한 오크와 트롤에서 영적 불안의 샘플을 추출하고"},completion={{374,1142139243},"얼굴은 기억이 안나지만 내 피부가  ⁇ 어가는 걸 가져오면서$B$B에스그램이 당신을 보내주신다고요. 마녀는 이미 밸리 오브 트레이션의 저주를 알고 있습니다. 지금도, 그녀는 그것을 해결하기 위해 의식을 하고 있습니다.$B$B트롤은 머리를 기울여 당신을 크기로 만듭니다.$B$B여기까지 왔으니, 의식과 함께 도와줄 수 있겠지"},progress={{23,1134276522},"뭐야, 낯선 사람?"}}
rows[1660019]={title={{15,1426591355},"길 은 닫혀 있다"},description={{575,830558279},"근처에서 우리는 세계 사이의 비늘이 희미해지는 동굴을 찾았습니다.$b$b마녀가 그녀의 연습생을 보내서 의식에 필요한 것들을 수집해줬어요 뱀, 박쥐, 거미의 영성$b$b<스와 ⁇ 리가 당신의 손에 작은 트롤 아이돌을 압축하고, 뼈에서 조각하고, 피가 붉은 보석으로 세트합니다.>$b$b장자리가 죽으면 네가 시작한 일을 끝내줄 수 있을까?"},objectives={{118,2001494408},"스와일리에게 주어진 자비를 이용해 악성 동굴의 입구를 지키는 마법적인 장벽을 깨라"},completion={{418,1992743831},"데이가 널 보내서 내가 죽었는지 확인해$B$B<트롤은 땅에  ⁇ 어져 있고, 각 숨은 찢어진 비명을 지고 있습니다.>$B$B그 암울은 효과가 없었고, 그 모든게 아니었지만, 그 동굴의 마법은 내 몸과 내 몸으로 날 찢어 버렸어.$B$B하지만 데는 내가 이리  ⁇ 처럼 살면서 살지 않았어.$B$B가까이 가자... 그녀의 목소리가 속삭이는 것처럼 떨어집니다."},progress={{84,1291191548},"<트롤은 깨져 있고, 그녀의 삶은 너무 무거운 무게를 가진 끈에 매달려 있습니다.>"}}
rows[1660020]={title={{18,184883665},"악성 삼위일체"},description={{539,992931787},"델 매치... 그녀는 당신의 동맹이 아닙니다. 그녀는 무슨 계획인지 모르겠지만, 그녀는 정신의 문제를 해결하지 않을 것입니다.$b$b왜냐하면 그녀는 그 사람을 일으킨 사람이니까요.$b$b그녀는 죽은 영혼들을 불러오고, 그들의 휴식에서 그들을 파고, 그들의 의식에 연료로 불태워. 그녀는 여전히 이 동굴에서 영의 본질을 필요로 합니다.$b$b하지만 대신 제 앞에 드림을 가져오면...$b$b내 상처가 심각하지만 내 결단력은 절대 강하지 않았어."},objectives={{144,1989954288},"악성굴을 괴롭히는 짐승들의 영적 본질을 수집해 보세요."},completion={{520,125935196},"본질적으로요!$B$B<그것의 심각한 상처에도 불구하고 트롤은 반쯤에서 일어나려고 노력합니다. 그녀의 몸통은 노력으로 떨고 있습니다.>$B$B세 가지 신성한 상징, 시니스트라 트라이드의 데 로와 연결됩니다: 지혜의 뱀 신, 음모의 뱀 신, 밤의 蝙蝠 신, 비밀의 신, 그리고 운명의 거미 신인 엘로르타 노 샤드라.$B$B더 오래되면, 당신이 내 손에 맡긴 힘은 마녀를 죽이는 데 충분할 겁니다. 하지만... <트롤은 피곤한 미소를 짓는다>"},progress={{36,1616984905},"마녀가 배신에 대해 돈을 지불할 거야"}}
rows[1660021]={title={{25,124388350},"다시 들 수 있게"},description={{519,2041010184},"본질의 힘은 델 마녀를 막기에는 충분하지 않을 것입니다.$b$b직접 마주해야 할 거야$b$b하지만 먼저... 원자론의 문제야$b$b델마녀는 델마녀의 영이 그녀를 상대로 일어날 것이라는 것을 알고 있었고, 그래서 그녀는 의식에 들어가기 전에, 그녀는 나를 명령했습니다.$b$b셰맨과 마녀의 대결을 하기 전에 그들을 해방시켜야 합니다. 동굴을 떠날 때, 바람이 오른쪽으로 흘러가는 길을 따라가세요."},objectives={{107,2143085341},"동굴 옆에 있는 원자들을 풀어주고 에스그라모르에게 히르사투타의 진정한 의도를 말해라"},completion={{352,1031809513},"난 바보였어, 내가 초자원자들에 손을 대면서 더 어두운 일이 일어나고 있다는 걸 알았어야 했는데$B$B대신, 나는 당신을 파견하여 마녀의 도움을 요청했습니다. 아이러니하게도, 마녀들의 불안의 원인은 바로 그 마녀였습니다.$B$B하지만 아직 늦지 않은데, 그녀의 계획을 어길 수 있습니다."},progress={{31,1611329758},"돌아왔어, 기다려왔어"}}
rows[1660022]={title={{17,1316297106},"악성 의식"},description={{566,1266594934},"우리가 지금 얘기하는 동안, 진동이 시험의 계곡을 지나가고 있습니다. 안자리와 히르사투는 의사의 충돌에 갇혀 있습니다.$b$b<상자가 눈을 감고 이야기한다. 마치 두 마녀의 싸움은 보이지 않는 세계에 속하는 것처럼>$b$b지금이나 절대 안 돼$b$b내가 원자들과 소통하고 마녀의 집중력을 깨고 노력하겠습니다. 그 동안... 당신은 이미 현장 경험을 쌓아왔어요."},objectives={{62,192474894},"히르사타 마녀와 맞서 그녀의 어두운 의식을 끝내라"},completion={{458,235843738},"끝났어 히르사타는 죽었어$B$B마녀가 여기 떨어진 모든 오크와 트롤의 영혼을 묶고$B$B다ంబ라는 속임수와 지혜의 웅장한 존재가 아니라 배신의 존재입니다.$B$B히 ⁇ 에크는 비밀과 밤의 웅덩이 아니라 목마른과 피의 웅덩이입니다.$B$B그리고 샤드라는 운명의 엮기꾼이 아니라 살인자, 거짓말쟁이입니다.$B$B그녀의 의식이 어떤 혐오를 낳았는지 상상해 보세요."},progress={{54,951572109},"영들은 불안해집니다.$B$B마녀를 막아야 돼!"}}
rows[1660023]={title={{21,121962510},"죄인 들 에게는 무죄 가 있는 사람"},description={{474,215158608},"마법사의 추종자들은 의식의 진정한 목적을 알지 못했을 수도 있습니다.$b$b이해해?$b$b오크의 얼굴이 어두워지고, 어깨에 놓은 손은 당신에게 요구하는 것과 비교하면 편안함을 줄 수 없습니다.$b$b다른 말로 하면, 당신은 그녀를 도달하기 전에 몇 명의 전사들을 뚫어야 할 것입니다. 대부분 무고한 사람들이, 이 이야기의 악당이라고 믿으며 죽을 것입니다."},objectives={{68,1323858708},"히르슈타로 가는 길을 지키는 우두파 신자들을 물리치"},completion={{86,1855147618},"오크가 주면만 하고, 그 작은 동작은 다시는 그 말을 하지 않기로 합의를 맺는 것뿐이다."},progress={{61,2082900801},"조금만 위로해 줄 수 있다면"}}
rows[1660024]={title={{30,587641331},"귀신 의도를 가진 괴물"},description={{511,1738493428},"안녕하세요$B$B저는 앤톤입니다. 문화유산연맹의 자랑스러운 회원입니다. 우리 여왕의 명령에 따라, 제 조직은 로데론 그래서 그것은 포세이큰.$B$B여기서 멀지 않은 곳에 서쪽으로 가는 길, 언덕 위로 올라가서 카인 가족들의 유산을 찾습니다.$B$B여기, 저는 당신의 지도에 제 동료들의 캠프의 위치를 표시합니다. 그들은 추가적인 손을 사용할 수 있습니다. 심지어 로데론  ⁇  전에, 소문이 있었다 고문이 저주되었다... 모든 특정 마녀 때문에."},objectives={{52,513861141},"레리치 리그 캠프에서 리셀 케인과 얘기해"},completion={{508,1791626223},"앤톤이 보낸 거야? 포세이큰 그가 몰려왔고, 그보다 더 많은 문제를 일으켰지만... 당신의 경동은 더 잘 보존되어 있는 것 같습니다.$B$B제 자신을 소개해 드리겠습니다.$B$B그래, 엄밀히 말하면, 이 땅에 대한 권리를 가진 마지막 살아있는 상속자, 적어도, 내가 있었을 것이다.$B$B하지만, 저는 여전히 제 책임감을 가지고 있습니다. 그래서 저는 유산 동맹에 가입했습니다. 제 가족의 재산을 회복하고 신종교회의 봉사에 기여하기로 결심했습니다."}}
rows[1660025]={title={{23,2144675110},"불안 한 가족 의 일원"},description={{585,1635388970},"우리 스스로 좋은 발전을 해왔지만 앞으로는 많은 일이 남아 있습니다.$B$B저는 곧바로 그 문제에 대해 이야기 할 것입니다. 스컬지가 오기 몇 년 전에 제 부모님은 사망했지만, 그들의 동굴은 비방과 굴욕을 겪었습니다. 저는 거의 이름을 말할 수 없습니다.$B$B내 조상들이 묻혀 있는 가족 동굴로 내려가서 그들의 영혼들을 위해 짧은 기도를 드라서 그들의 영혼을 그들의 유해로 끌어들여서"},objectives={{122,1609284744},"카인 가족 동굴에서 죽은 리셀의 유물을 정화하고 그들의 영을 사후로 보내라"},completion={{334,1466511104},"보볼드, 당신은 하위급이라고 말합니다. 폭도, 가해자, 소형 도둑. 그들이 부패하도록 해! 나는 개인적으로 그들의 굴이 비염으로 질식하는 것을 볼 것입니다.$B$B당신들의 작품에 대해서는 인상적이긴 하지만, 유적에 있는 죽음의 추적자는 영들이 더 이상 그 방과 홀에서 돌아다니지 않는다고 보고했습니다.$B$B그 말은 무슨 뜻인지 알겠나?"},progress={{90,1480854886},"내 가족들의 유물을 깨끗하게 해냈어?"}}
rows[1660026]={title={{21,63508574},"말 할 수 없는 비밀"},description={{542,614493814},"정신이 문제인 것, 또 다른 문제도 있습니다. 제 동료들의 능력보다 훨씬 더 많은 문제입니다.$B$B여동생 프리스킬라가 그녀의 이름을 저주하고, 이 숙소를 마법의 동굴로 바꿨고 그녀의 최악의 실험은 지하에 봉쇄되어 있었고, 그 열쇠는 우리가 방금 알게 된 것처럼 세 조각으로 깨져$B$B죽여서 열쇠 조각을 되찾아줘"},objectives={{81,2104349266},"이마네의 마요르도모, 하녀, 그리고 스태블 마스터의 핵심 조각들을 찾아보세요."},completion={{96,1998565345},"열쇠 조각은?$B$B멋지다, 난 너무 무례해$B$B잠깐만요"},progress={{67,1590112034},"열쇠 조각이 있어?"}}
rows[1660027]={title={{26,1784931632},"카인 가문의 참 상속자"},description={{403,1623762562},"- 다 됐어$B$B\"Exsangue는 원본의 찢어진 잔해에서 조각된 열쇠를 주는데... 그 수치가 그 문 뒤에 있는 것만큼 의심스럽다\".$B$B내가 널 돌고 다니는 동안, 난 네가 거기 갇힌 모든 걸 처리할 때,$B$B한 번 이상 울음소리, 그리고 삐삐 소리 들었을 것 같았어요. 조심하세요."},objectives={{66,2046054646},"열쇠를 이용해 지하에 들어가서 내부의 생물을 물리치세요"},completion={{388,1696106114},"<리셀은 당신이 본 것을 이야기하면서 천천히 머리를 흔들고 있습니다.>$B$B그 생물은... 나는 소문을 들었지만, 내 여동생에게는도 믿을 수 없을 정도로 괴상한 것 같았다.$B$B프리스킬라가 악마와 동행한 것 같아서$B$B어쨌든, 당신은 레거티스 리그에 큰 공헌을 해왔고, 이 과정에서 내 가족 이름의 존엄성을 회복시켰습니다."},progress={{106,1714173879},"네가 그 일을 해냈어, 그렇지 않으면, 넌 이렇게 무관하게 여기 서서 나와 얘기하지 않을거야."}}
rows[1660028]={title={{16,1495989795},"귀신 한 유산"},description={{514,2070437455},"레거티스 리그가 어떻게 자금을 지원하는지 아세요?$B$B여왕은 우리가 되찾은 보물 중 일부를 보관할 수 있게 해줬고, 그래서 지금까지 우리는 요새보다 훨씬 더 많은 궁전을 복원해 왔습니다.$B$B케인족이 멸망하기 전에 이 왕국에서 가장 부유한 가족 중 하나였는데$B$B뭘 발견하느냐에 따라 협상이 될 수도 있어요$B$B하지만 조심해, 이 집의 전주인 리셀의 여동생이..."},objectives={{90,1133464288},"케인 가문의 유산을 탐험하고 남은 귀중품을 되찾고 트리스로 가져와"},completion={{519,1994019834},"<만욕이 색을 가졌다면, 이 포세이큰의 눈의 노란색이 될 것입니다.>$B$B ⁇ 한 그림... 크리스탈 공 (아마도 저주받은) 은 축하하기 전에 평가해야 할 보석이고, 가치는 순전히 감성적인 가족 표지판이라고 할 수 있습니다.$B$B사실 별로 없는데, 그녀는 아무것도 아닌 것처럼 손을  ⁇ 어요. 하지만 그녀의 눈은...$B$B이 돈으로 많이 살지 못하겠지만, 아무것도 안 돼는 게 낫다. 가족 표지판에 대해서는..."},progress={{40,69503870},"그 안에 가치 있는 게 발견했나?"}}
rows[1660029]={title={{33,1617039997},"길 에서 쌓아온 친구 들"},description={{596,2042412143},"내가 여기서 못 지낼 수 있어 그리고 이 애들은 계속 새로운 방법을 찾아서 곤경에 빠지게 해$B$B우리가 올바른 재료들을 얻을 수 있다면 도움을 줄 수 있는 사람을 알고 있습니다.$B$B난 여기 남아 캠프를 보호해야 하지만 넌 이미 스스로 처리할 수 있다는 걸 증명해줬어$B$B ⁇ 비, 괴물, 곰 등이 그 집안에 돌아다니는 생물을 죽여라. 그들이 남긴 것을 가져오지 마. 그들의 장기가 휘발성이 있고, 제대로 다루지 않으면 망할 수도 있고, 더 나쁜 것도 될 수 있습니다."},objectives={{67,172572195},"케인 매너를 돌아다니는 생물을 죽여라: 좀비, 괴물, 곰"},completion={{379,2097619931},"돌아왔군. 지나온 길에 시체가 제법 쌓였던데.$B$B좋아.$B$B<포세이큰이 시체에서 거둘 것을 떠올리며 히죽 웃는다.>$B$B이것들과 약간의 전기만 있다면, 내가 아는 포세이큰이 친구 하나를 꿰매 만들어 주겠지. 우리에게 손을 보태 줄 친구 말이야. 손 하나, 어쩌면 둘이나 셋을 말이지. 우리가 ‘누더기골렘’이라고 부르는, 덩치 크고 퉁퉁 부은 괴물 말이야."},progress={{27,1563459590},"쇼핑은 끝났어?"}}
rows[1660030]={title={{17,1850358230},"죽음과 추모"},description={{449,774466719},"<타우렌은 측정하고 판단하는 시선으로 당신을 키우게 합니다.>$b$b강하고 잘 지어진 용감한$b$b<순간간 잠시 멈추고 나서 그는 확신을 가지고 머리를 숙이고 있습니다.>$b$b네, 유용할 수도 있어$b$b이 평야 건너편에는 단독한 한옥이 있습니다. 제 귀족 여인의 망명 장소입니다.$b$b그녀는... 강경한 판사이지만, 관대합니다. 7명의 그림토메 해적들을 죽여서 그놈의  ⁇ 을 증명해 줄 것입니다. 그녀는 당신을 보상할 것입니다.$b$b그녀는 당신에게 가장 귀한 목적을 맡길 것입니다."},objectives={{121,1985919256},"붉은구름 고원에서 그림토템 약탈자 일곱을 처치하십시오. 증거로 갈기를 가져가 레드혼 여군주의 주인에게 전달하십시오."},completion={{192,1656390106},"이건 어떤 선물도 아니고 7명의 전사로부터 받은 7개의  ⁇ 이$B$B만약 당신이 내 충성스러운 레드호른이 보낸다면, 당신의 서비스를 받아 들일 수 있는 영광이 될 것입니다."},progress={{44,123949509},"내가 널 불러왔어?"}}
rows[1660031]={title={{15,457062793},"죽음 과 추방"},description={{622,1370964224},"난 모리가 홀로후프, 3개의 토템의 왕인  ⁇ 독 말고르 홀로후프의 딸입니다.$b$b난 항상 여기 살지 못했는데 한 번 아버지로부터 삼종을 해방시키려고 했지만 실패했어요. 제 배우자는 그 실패를 위해 목숨을 바쳤고, 저를 따르던 모든 사람들이 그랬죠.$b$b하지만 내 아버지는 내 말을 실행할 용기가 없었고, 대신 날 여기로 내쫓아 버렸습니다.$b$b하지만 그가 모르는 것은 마을 내와 그 너머에도 여전히 동맹들이 있다는 것입니다.$b$b산을 따라가서 현명한 나우콜을 찾아서 이 반지를 가져가라"},objectives={{100,733102558},"그리모테마 산길을 따라 하드 베킨으로 이동하고 모리가 홀로후프 ⁇ 의 반지를 세이즈 나우콜에게 보여주십시오."},completion={{270,2009591021},"이 반지는...$B$B<타우렌은 오랫동안 침묵하고, 그의 시선은  ⁇ 나무 속의 거북처럼 불안하게 깜박이는 것 같다.>$B$B모리가 너를 챔피언으로 선택했어 내가 못 보는 걸$B$B상관없어, 할 일이 있어"},progress={{4,273767400},"- 그래?"}}
rows[1660032]={title={{18,1522164006},"죽음 과 수치심"},description={{638,1826524519},"15명의 말고르마 전사들을 상대로 살아왔다면, 아마도 독재자 자신도 상대로 기회를 가질 수 있겠지만, 마을 전체를 상대로는 그렇지 않을 겁니다.$b$b우리들 중 한 명처럼 입으려면 위장일 필요가 있을 거야$b$b모리거 반란 이후, 그녀의 죽은 전사들은 장례식 의식의 명예를 거부당했습니다. 그들의 시신은 여전히 잔디와 점토에 흩어져 있습니다. 사체로 남겨졌습니다. 그들의 사물이 놓치지 않을 것입니다. 그리고 새우들은 그들을 벗은 것에 대해 당신에게 감사 할 것입니다.$b$b마르고르프에 충성한 죽은 사람들만 의식을 받았어요. 그들의 시체에서 장갑을 찾을 수 없습니다. 하지만 훨씬 더 귀중한 것을 찾을 수 있습니다."},objectives={{102,447965940},"세 토템 전사들의 방어구 조각과 신분을 나타내는 펜던트를 모아 변장을 완성하십시오."},completion={{42,1075738106},"위장용으로 필요한 모든 걸 가져왔어?"},progress={{161,1512705726},"아직 위장용품은 안 가져왔어?$B$B이미 15명의 전사를 물리쳤을 수도 있지만, 당신들을 상대로 연합한 마을은 살아남을 수 없습니다."}}
rows[1660033]={title={{17,63705328},"죽음 과 정의"},description={{262,1063740414},"마을의 가장 먼 끝에 있는  ⁇ 골호프마를 찾을 수 있습니다. 언덕 꼭대기에 있는 가장 큰 동굴에서요.$b$b그가 가는 동안 머리를 높이 올려다보아라. 어떤 시선을 만나지 마라. 자신 있게, 자부심을 갖고, 자부심을 가지고, 심지어는 자존심을 가지고. 그의 전사들이 그렇게 행동한다. 그는 그렇게 한다."},objectives={{113,25910003},"변장할 준비가 되면 나우콜과 대화하십시오. 세 토템에 잠입하여 말고름 할로우후프를 처치하십시오."},completion={{296,2027238813},"내 아버지는 죽었나?$B$B모리가의 눈은 젖어지고, 그녀의 모습은 슬픔이나 위로가 될 수도 있고, 아마도 둘 다 눈물이 될 수도 있습니다.$B$B즉, 3토템으로 돌아갈 수 있다는 뜻이죠.$B$B그리고 모든 것을 바로 잡으세요.$B$B<모리가의 눈물은 그녀의 미소의 구멍에 사라지고 갑자기 그녀는 더 이상 그렇게 부드러운 것처럼 보이지 않습니다.>$B$B제 방식대로 정해"},progress={{68,52177462},"다시... 악명  ⁇ 이군요. 나우콜을 찾았나요?"}}
rows[1660034]={title={{17,1765911613},"웃음 으로 인한 죽음"},description={{530,1342550024},"내가 너한테 조금 동정심을 느끼지 않나? <현장애인]은 입을  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어$b$b너랑 함께 있어 다행이군$b$b<그  ⁇ 은 미소로 뻗어 있고,  ⁇ 은 치아줄이 반짝이는 것 같다.>$b$b마을에 가서 토테마를 통해 내 축복을 전달해줘서 지켜주는 영들이 화를 낼 거야$b$b내 때문에 해줘... 어쩌면 운명이 너한테도  ⁇ 을 줄 거야"},objectives={{109,2001912448},"큰 고래의 축복을 마을 토테마에 전달하고 그들을 보호하는 수호자 영들을 물리치십시오."},completion={{296,1711046710},"<하이엔아는 울고 웃고 울고, 마치 당신에게 주어진 임무가 지금까지 전해 내려온 가장 큰 농담처럼>$B$B잘했어... 아주 잘했어!$B$B마을의 영들은 화를 내리고, 그들은 그것을 얻었습니다. 그들은 나에게 굴욕을 당했고, 망명했습니다.$B$B내 미소는 운의 미소입니다. 이제..."},progress={{126,227817039},"<단지 앞에  ⁇ 은 모양의 존재가 펼쳐져 있는데 거의 보이지 않는 것 같고, 마치 육신 세계와는 완전히 관계가 없는 것 같다.>"}}
rows[1660035]={title={{16,970724288},"내가 헌신 하는 자"},description={{535,1478241469}," ⁇ 할로를 인도하는 영들이 많고, 몇몇은 더 유명하고, 잘 알려져 있고, 모든 부족에서 존경받고 있습니다.$b$b산길 끝에, 하드 베인 한 모퉁이에, 위대한 고래의 정신을 기리는 단독 토테임이 있습니다.$b$b저는 망명에서도 그녀에게 많은 빚을 지고 있습니다. 그녀의 지혜는 이 오랜 세월 동안 저를 인도해 왔습니다.$b$b내 이름을 위하여 제물을 드라라 내 적들의 뼈와 그 잔해들이 길에서 내려오는 큰 짐승들의 뼈를 가져라$b$b우리 아버지, 독재자를 무너뜨릴 때 그녀의 축복이 필요할 겁니다."},objectives={{93,1757423098},"산길에 있는 뼈들을 모아 하드 베킨의 대왕조사 제단에 바쳐라"},completion={{290,1060628416},"<하이나의 영은 가까이 갈 때 치아를 벗고 있습니다. 경고인지 웃는지 알 수 없습니다.>$B$B모리거야?$B$B<개골을 찢어 놓은 미치광이 웃는 것>$B$B난 기뻐, 타우렌은 항상 나를 즐겁게 하는 방법을 찾는데$B$B잘 됐어요, 잔해를 가져갈게요"},progress={{126,227817039},"<단지 앞에  ⁇ 은 모양의 존재가 펼쳐져 있는데 거의 보이지 않는 것 같고, 마치 육신 세계와는 완전히 관계가 없는 것 같다.>"}}
rows[1660036]={title={{13,1641683397},"신탁의 우상"},description={{455,2040061828},"<격렬하게 몸부림치던 멀록이 축축한 흙바닥에 쓰러집니다. 몸에서 떨어진 구슬 하나가 굴러와 당신의 발치에서 멈춥니다.>$B$B<자세히 살펴보니 보석이 아니라 눈알입니다. 매끈한 표면에 주변과 전혀 다른 희미한 광경이 비칩니다. 마치… 앞으로 일어날 일을 보여 주는 듯합니다.>$B$B<다른 점쟁이들도 처치하고 그 기이하고 눈먼 눈을 살펴보는 게 좋겠습니다.>"},objectives={{91,1047607743},"그늘샘을 돌아다니는 멀록 점쟁이에게서 예언자의 신탁 구슬 세 개를 모아야 합니다."},completion={{453,886835979},"<사제님은 당신이 사건을 회상하면서 주의 깊게 듣습니다.>$b$b흥미로운 발견입니다.$b$b이상하게도... 우리가 환상을 받은 거의 모든 성도들은 어떤 형태로든 맹인증으로 고통받았죠.$b$b어쨌든 <그분들은 미루로크의 눈을 쓰레기통에 던져버립니다> 미래가 무엇을 가지고 있는지 아는 사람은 오직 빛 입니다.$b$b이 이단적 존재들 속에서 본 것 같든 속임수만였어. 무성들은 인간의 정신을 모욕하는 것이다."},progress={{37,827380974},"무엇을 도와드릴까요, 그대여?"}}
rows[1660037]={title={{24,1118587397},"불안 은 혀 를 흔들게 한다"},description={{379,679895352}," ⁇ 불족은 정신의 불안에 시달리는 유일한 사람들이 아닙니다.  ⁇ 불고로에서는 우리는 같은 문제를 직면합니다.  ⁇ 불의 의식이 그것을 정해 놓기 전까지는, 우리는 가능한 한 그것을 처리합니다.$b$b여기 온 이래, 내가 물어볼게$b$b몇 가지 딕 마스크가 만들어져 있어 계속  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어$b$b몇 개를  ⁇ 어, 그들을 침묵시켜라"},objectives={{47,1058477850},"Zeb ⁇ Goro 주변에서 말하는 티키 마스크를 파괴하라"},completion={{239,190787861},"드디어 침묵이 됐어, 축복받은 침묵이 됐어, 그 소리가 어떻게 들리는지 거의 잊었어$B$B마스크가 너무 많은 문제를 안겨주길 바랍니다.$B$B얘기가 좋아지, 너한테는 말할만한 게 없어"},progress={{47,1815434975},"마스크를 깨뜨렸다고 믿어요"}}
rows[1660038]={title={{20,883169726},"우리 중 가장 슬픈 자"},description={{276,321205589},"더 많은 책을 삼키려는 불길의 굶주림에 사로잡힌 자가 있다. 더 태울 불경한 책이 없어지자 불길은 성전마저 삼키기 시작했다.$B$B텅 빈 눈구멍에는 불이 타오른다. 이제 흘릴 눈물조차 남지 않았다.$B$B오직 죽음만이 저주받은 검열관을 놓아줄 수 있으리라…"},objectives={{61,172881967},"비밀 이단심문 지하감옥에서 저주받은 검열관을 쓰러뜨려야 합니다."},completion={{272,290154419},"불은 그 욕망을 충족시킬 사람이 없으면 영원히 불지 않을 수 있습니다.$b$b그를 죽여서 그를 해방시켰어 이제 불꽃은 그의 뼈를  ⁇ 어  ⁇ 어 먼지와  ⁇ 을  ⁇ 어 버리는 것만으로 만족해야 한다$b$b하지만 이 방은 먼지와 화염보다 더 많은 것을 담고 있어"},progress={{51,554880623},"검열관에게 죽음과 자유를 모두 안겨 주었느냐?"}}
rows[1660039]={title={{20,618619308},"오른손 을 찢어"},description={{586,1272473773},"망명으로 갔어?$b우리 위에 있는 언덕에 진영을 세웠어요$b$b마지막으로 얘기한 건, 그녀는 제가  ⁇ 어내지 못했던 말을 했습니다.$b거짓말보다 더 강한 거짓말을 옹호하는 사람은 그 거짓말에 믿는 바보뿐이다.$b$b그 분의 오른손이라고 부르는 사람은 그 증거입니다. 그는 평범한 추종자 아닙니다. 레드나는 그가 그의 주인보다 더 잔인하고 더 독재적이고 더 광신적인 것이라고 맹세합니다.$b$b만약 당신이 할 수 있는 힘을 가지고 있다면, 광명도시를 지나가는 동안 그를 죽여라, 그리고 레드나에게 보고하라."},objectives={{50,1453725319},"광명시에서 그의 권좌를 물리치고"},completion={{255,191291948},"<왜란은 주의 깊게 듣고, 거의 치아 없는 미소를 수지 못한다.>$B$B저 놈을 죽였어?$B$B<그녀의 독성 얼굴이 밝아진다.>$B$B네가 그에게 준 것은 그가 왔던 것이다. 내가 네게 준 것은 네가 마땅히 받은 것이다. 네가 내게 준 기쁨에 합당한 보상이다."},progress={{62,1477208638},"죽였어? 숨 쉬는 거? 고통 받는 거 확인해!"}}
rows[1660040]={title={{17,269162581},"불안 한 속박"},description={{362,1797047424},"골반으로 가고 있는 거야?$b$b<정말 당신이 그 일에 적합하지 않은지 결정하기 전에 당신의 가치를 평가하는 엘프 눈입니다.>$b$b내장과 뼈의 괴물들이 골관 터널을 지나가며 시체들이 씹을 것을 갈망하고 있습니다. 벌레들은 어리석은 비독자들일 뿐이죠.$b$b그 괴물을 죽여라... 신조가 널 대부하게 보상할 거야"},objectives={{52,1883642937},"달 골반에 부패한 육류를 물리치"},completion={{137,1282426597},"이 혐오... 죽은 거냐?$b$b<엘프가 당신의 옷에 눈길을 끌고, 피가 흐르는 점막으로  ⁇ 어져 있다.>$b$b이 혐오가 죽었어$b$b멋지네요"},progress={{30,243946726},"이 혐오... 죽은 거냐?"}}
rows[1660041]={title={{16,578066150},"아저르 의 왼쪽 문"},description={{307,1731769443},"거미의 영혼, 뱀, 박쥐의 존재가 느껴지고, 그 힘은 동굴의 장벽에 퍼져나가고 있습니다.$b$b우리가 성공한다면... 내가 살아서 이 곳을 탈출한다면... 그 생물을 죽이고, 그 생물이 속한 곳으로 다시 보내게 될 거야."},objectives={{51,787876807},"악성 웅덩이에 테클라 ⁇ 투를 물리치고"},completion={{209,1803062084}," ⁇ , 바뀐거야... 당신은 죽었어 수호자 정신이 있잖아?$B$B잘 해, 아마 네가 마녀를 상대로 할 기회가 있을 거야$B$B여기 이 작은 표지판을 가져와"},progress={{80,249444859},"영으로... 날개를 찌르며..."}}
rows[1660042]={title={{8,1492688079},"난 집에 있어"},description={{459,531910088},"우리는 괴물입니다. 하지만 우리의 운명보다 더 슬픈 것은 우리의 숲과 들에서 돌아다니는 짐승들의 혼란스럽고 고통스러운 불행입니다.$B$B한 번은 내 마음이 그들을 아끼었을지도 모르지만, 더 이상 아끼지 않을 것입니다.$B$B특히 카인 가문의 늙은, 충실한 개견$B$B맨션을 둘러보고 그의 무덤을 찾아서 그가 정말로 죽은지 확인해봐요. 그는 그의 주인 냄새를 맡고 그를 삼키는 최초의 죽은 마스티프가 아니겠죠."},objectives={{48,352912565},"이 집 뒤에 있는 카인의 사냥개를 물리치"},completion={{225,1158269020},"그 개... 죽은 거요?$B$B< <이 포세이큰은 슬픔으로 가득 차 머리를 흔들고 있습니다.>$B$B썩은 것이 많은 사람들을 왜곡시켰으니 위험을 감수하지 않는 것이 더 안전합니다.$B$B누가 알겠어요... 어쩌면 이 개는 다른 사람이었을지도 모릅니다.$B$B여기, 네가 이겼어"},progress={{74,2009287664},"거리에서 짐승의 울음을 들었을 것 같네요 빨리 끝내세요"}}
rows[1660043]={title={{21,922821736},"캐리온을 위해 싸워"},description={{431,1148812312},"아마도 당신은 그 비참한 존재에 주목했을 것입니다. 새가 하드 베이징을 돌고, 전전장에서 흩어져있는 사체를 지배하고 있습니다.$b$b그는 외치의 반향에 불과하지만 저 아래로 갇혀 있고 그가 자유롭게 날아다니는 것은 내 치아가 가려움증입니다.$b$b내가 아니라면 보상으로 죽여$b$b<하이나 영은 날카로운 치아로 가득한 미소를  ⁇ 니다.>$b$b그래, 그 보상도 가치가 있을 거야"},objectives={{46,2116675015},"하드 베인에서 잔인한 캐리온 정신을 물리치"},completion={{306,1121775790},"드디어!$B$B배수꾼이 시체로 변해버렸어 맛있지 그의 아버지는 내가 그의 수많은 악당 중 한 명을 죽이기 위해 음모한 것을 알게 되면 화가 나$B$B또 다른 불만이 우리 긴, 피난한 수치를 추가해야 합니다.$B$B마지막, 승리한  ⁇ 은 영의  ⁇ 을 끝낸다.$B$B약속은 약속이야, 상을 현명하게 선택해"},progress={{97,1819977573},"<하이엔아는 공기를 냄새가 맡고, 그 다음 하늘을 바라보고 있습니다.>$B$B거북이... 끝내주신가요?"}}
rows[1660050]={title={{17,236816364},"약사 플레머"},description={{246,847838200},"여기 좋은 일을 해냈어$b$b데스넬에 다 끝났을 때, 브릴의 약사 플레머를 방문하세요.$b$b내가 할 수 있는 대로 그가 필요한 고기를 보내줄게"},objectives={{38,2068819295},"브릴에서 약사 플레머와 이야기해"},completion={{288,601259403},"<포세이큰은 파열된 악기로 악보를 내세우고, 그의 집중은 그의 손에 실험에 고정되어 있습니다.>$B$B그리고 당신은...?$B$B아, 아, 아.$B$B잘, 난 기다릴 수 있어, 하지만 절대 무력하진 않을거야 에릭이 약속한 육체는"}}
rows[1660051]={title={{30,1659743670},"그 부분 의 합 보다 더 많은 것"},description={{578,541662883},"어떻게 이렇게 표현할 수 있어?$b$b혐오는 그 부분들의 합보다 더 많죠. 스컬지에 대한 비밀 성분은 불신의 한 줄기였습니다. 우리는 왕립 약학회에서 더 창의적인 해결책을 찾아야 합니다.$b$b브릴 위에 있는 탑은 내가 몇 마일 동안 본 것과는 다른 곰팡이 성장이 있습니다. 죽음과 시체신술에 매운 채로, 그 소포는 여전히 그 본질으로 발음을 내고 있습니다.$b$b발견한 모든 스포를 가져오세요. 그 스포르는 보호자의 피부에 붙어 있거나 바닥에 흩어져 있는 점막 세포에 갇혀있든가."},objectives={{178,618014096},"브릴을 바라보는 버려진 탑의 곰팡이에 있는 네크로틱 스포를 수집하세요. 두 가지 형태로 나타납니다."},completion={{481,583548832},"< 포세이큰 의사는 검사를 통해 샘플을 검사합니다. 그 기준에 맞으면 그의 시선은 좁아지고, 냉정하게 인내하며, 희하고, 경멸적인 미소가 나타납니다.>$B$B좋은 일이었는데, 놀라웠어요.$B$B스포는 전성 에너지를 발사하고, 과학에 도움이 될 수 있는 잠재력을 발휘하기 전에 긴 치유가 기다리고 있습니다.$B$B하지만 이것과 몇 조각으로, 당신은 곧 보게 될 것입니다. 이 전문적인 손으로 꿰매고  ⁇ 은 내 건축물의 죽은 육체는"},progress={{25,441957021},"스포를 가져왔어?"}}
rows[1660052]={title={{17,2029519165},"무방한 자세"},description={{636,999287357},"치즐, 해마어, 광장, 대구리, 여기 있는 마슨 로지, 칼, 활, 막대, 도끼,$b$b이곳 동쪽, 브라이트워터 호수에서 파묻힌 반란군들은 암흑의 여자의 통치를 거부하고 있습니다.$b$b내 동생도 그 중이야 내가 세브렌 판사가 그의 죽음의 스터커를 보내길 기다린다면, 내 이름이 불명예로 불어질 것이고,$b$b반란군을 몰아내고, 아무도 살지 말고, 무엇보다도 내 동생이 떠나지 않도록 하라."},objectives={{91,793650664},"밝은물 호숫가에 진을 친 포세이큰 반란군을 찾아 처치하십시오."},completion={{385,653547072},"배신자 군대를 제거했나?$B$B<델카드 세딩의 얼굴에 미소가  ⁇ 니다. 그의 동생의 죽음을 확인하는 동안>$B$B이제 아무도 알리크가 우리 가정을 얼마나 부끄럽게 만들었을지 알 수 없을 거야$B$B그는 자신이 어떤 사람이든 받아들이지 않았습니다포세이큰하지만 어떤 문제가 해결되지 않을 때, 그것은 문제가 되지 않고 다른 것이 되고, 현실이 됩니다."},progress={{50,250191806},"그 문제를 해결해 본 적 있나요?"}}
rows[1660053]={title={{22,1411344880},"스카렛 편지"},description={{372,136093185},"<알리크 사딩과 붉은십자군의 특정 벨몬트 사이의 편지 교환>$b$b반란자들은 십자군과 접촉한 것으로 보이며, 그들의 발리사드의 문들을 잘짐으로 열려고 했습니다.$b$b<사람들의 캠프는 북쪽으로 표시되어 있습니다. 짧은 방문은... 이 땅을 누가 지배하는지 상기시키기 위해서입니다.>"},objectives={{56,1676667193},"붉은십자군 캠프를 찾아 그들의 에이전트를 죽여라"},completion={{368,1919514452},"내 동생과 반란자들은 붉은십자군와 접촉하고 있었고...$B$B<델카드는  ⁇ 한  ⁇ 을 내보내서 치아를 풀고 벽에  ⁇ 을 때려요.>$B$B내가 널 이 일에 유도한 것 같군, 그들은 어떻게든 죽게 될거야, 네 손에, 아니면 십자군들의 자비로$B$B얼마나 순진한지, 결국 위협은 아니었어요"},progress={{51,111500251},"<델카드는 천천히 머리를 흔들고 마치 자기 자신에게 그랬듯이>"}}
rows[1660054]={title={{12,488728385},"잠시 머물"},description={{126,1073994971},"<보아도 당신은 반시의 설교를 듣기 위해 준비된 희귀한 호기심 있는 영혼 중 한 명인 것 같다.>$b$b<아마도 공유할만한 게 있어요>"},objectives={{91,732773808},"소음에서 잠시 떨어져 서둘러 잠시 동안 어둠의 사제 아샤라를 들으세요"},completion={{115,104002280},"호기심은 잊혀진 그림자의 숭배에서 우리가 가진 세 가지 덕목 중 하나가 아닙니다.$B$B하지만 그것은 그들의 전방입니다."}}
rows[1660055]={title={{22,1873014652},"두고 온 하녀"},description={{441,668957513},"당신은 하루 종일 수도원에 들어와 나오고 있지만, 저는 아직도 제 동생을 본 적이 없습니다.$b$b- 그놈을 못 뽑아냈어$b$b그녀의 긴 고갈한 숨쉬는 충분히 말해줍니다.$b$b다시 나가면 한 번 더 부탁을 해주실까요? 수도원으로 가는 길에 저는 제 하녀 한 명을 골드샤이어에$b$b듀시네아라고 부르세요 내가 늦을 거 알려주세요"},objectives={{43,471396560},"골드샤이어에서 비앙카의 하녀 둘시네아를 찾아야 합니다."},completion={{244,2035351975},"내 부인이 비앙카가 보냈어?$B$B<두르신아는 어색한  ⁇ 을  ⁇ 다.>$B$B그래서 그녀는 늦어질거야... 그 동생은 문제일 뿐이야$B$B어차피 엄마의 약은 기다릴 수 없어"}}
rows[1660056]={title={{16,33761222},"아그리아의 약"},description={{517,937565384},"아그리아 스파다 여인은 나이로 둘러싸여 있는 여성입니다. 최근에는 침대에 잠들게 하는 병들이 많이 앓고 있습니다.$b$b오직 한 가지만 그녀를 쉬게 해줍니다. 그녀의 석사 화학자가 만든 드래프트$b$b몇 가지 재료들을 수집했으나 목록은 길고 바쁜데 여전히 엘그리스 꽃잎, 덩 카자드 술 농약,  ⁇ 수,$b$b시장을 돌아다니고, 땅을 가져가면, 내 여자의 숙소로 보고해줘요."},objectives={{143,1850508036},"골드샤이어 시장에서 엘그리스 꽃잎, 던 카자드 술 농축액, 호박 주스, 멀록 눈알을 사야 합니다."},completion={{352,706969088},"또 다른 보행자?$B$B레이디 비앙카와 모로이가 무슨 짓을 하고 있는지 모르겠지만, 그들의 어머니인 아그리아는 시간이 얼마 남지 않았습니다.$B$B알디아는 노부에게 애도심을 표합니다. 그녀는 이미 반 묻혀있는 것처럼 보입니다.$B$B재료는... 가지고 있나요? 잘해. 알케미스트에게 넘겨줄게요."},progress={{50,1546533193},"무슨 일이 스파다 유산을 데려왔어요?"}}
rows[1660057]={title={{23,93199156},"7년의 불운"},description={{408,870627616},"- 그래요$b$b<주장님께서는 긴 시선을 보실 수 있습니다.>$b$b떠나기 전에... 한 가지 더 도와줘요.$b$b내 여자의 병은 육체적인 것이 아니라 마법적인 것 같다는 생각이 들었어요$b$b그것은 깨진 거울에서 시작되었습니다. 그리고 당신은 그들이 말하는 것을 알고 있습니다. 내가 얼마나 철저하게 있었는지, 조각은 계속 나타납니다.$b$b친절하게 대할 수 있을까요?"},objectives={{100,1130998341},"알디아 크레용이 아그리아 스파다 부인을 괴롭히는 저주의 원인으로 지목한 깨진 거울 조각을 살펴봐야 합니다."},completion={{299,1868129251},"그래서 내 본능이 옳았어요.$B$B노년기에 대한 치료가 없겠지만, 저주가 깨지면 적어도 아그리아 여인의 끔찍한 고통은 완화될 것입니다.$B$B<그는 말을 할 때, 년이 나타납니다:  ⁇ 은 얼굴에 깊은  ⁇ 을 자르고, 눈물 눈은 사용되었습니다; 그는 그가 봉사하는 여인보다 거의 젊어.>$B$B열심히 봉사해 주셔서 감사합니다."},progress={{31,1303327677},"거울 조각을 찾았어?"}}
rows[1660058]={title={{16,759637906},"벌레 먹은 사과"},description={{415,1253043690},"속삭이는 것 같지만, 나는 바닥에 귀를 기울여서 잠들어요!$b$b그들은 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고 파고$b$b코볼드, 코볼드, 더 많은 코볼드, 우리 발 아래로!$b$b그들의  ⁇ 을 찾아 불태워버리고 큰 무거운 해마로  ⁇ 어버리고$b$b<그녀는 스스로 웃고, 그리고 중간 거리에 쳐다보고>"},objectives={{53,565664309},"골드샤이어 주변의 코볼드 굴을 찾아 파괴해야 합니다."},completion={{228,911722133},"<개정말의 클라라는 오른손에 사과를 들고, 가장 소중한 소유물처럼 감상하고 있다.>$B$B골드샤이어는 이 사과와 같습니다.$B$B천천히, 그녀는 그것을 씹을 것을 보여주기 위해 돌고, 겉보기에도 불구하고 내부는 부패하고, 벌레가 먹어 버렸어요."},progress={{80,1994993919},"그 벌레들은 살아있지 않죠 골드샤이어 터널 아래로 넘어갈 것입니다."}}
rows[1660059]={title={{22,685308599},"골드샤이어의 인심"},description={{469,957579465},"- 안녕하세요$b$b난 토름 하브렌드 토름 시장 골드샤이어브룩과 그의 집 대신 봉사하고 있습니다.$b$b이 대당의 그림자 속에서 임시 캠프를 발견했을지도 모릅니다. 골드샤이어 수많은 난민들을 수용하고 있습니다. 서부 몰락지대가끔은 우리가 할 수 없는 일이...$b$b하지만, 그들이 굶어죽으면서 돌아가지 않을 겁니다. 마을을 돌아다니며, 작물마다 조금씩 가져와서 캠프로 데려갈 겁니다."},objectives={{127,1712382180},"골드샤이어 주변 농장에서 멜론, 호박, 사과를 모아 피난민의 지도자 엘도르 해머에게 전달해야 합니다."},completion={{89,106421408},"내 사람들은 잊지 않을 거야 골드샤이어친절한 사람$B$B언젠가 우리는 그것을 완전히 갚을 것이라고 믿습니다."},progress={{15,159386007},"무슨일이지?"}}
rows[1660060]={title={{12,488728385},"잠시 머물다 가세요"},description={{222,691318090},"마을의 역사를 살펴보면 내가 가장 권위 있는 사람이야$b$b<노인 마법사는 대화에 열망하고 거의 절망하는 것 같다.>$b$b<아마도 공유할만한 게 있어요>"},objectives={{82,2059067580},"소란스럽고 바쁜 일상에서 잠시 벗어나 앨리스카 렌드의 이야기를 들어야 합니다."},completion={{34,704283051},"너무 지루하지 않았으면 좋겠어요!"}}
rows[1660061]={title={{17,987880167},"에스그라모르의 주인"},description={{363,140353807},"시험의 계곡은 네 이름을 따왔어$b$b내 집은 여기 있지만 도로에서 전화가 왔어요$b$b레이저 힐에서 한 지혜가 있어 네 도움이 필요해 카라가르라는 이름을 알아봐"},objectives={{33,1414099015},"라저힐의 카라거와 얘기해"},completion={{353,1295717693},"<오크 늙은이, 시험의 계곡에 대한 당신의 이야기를 반발한 시선을 가지고 듣는다.>$B$B저는 히르사타를 좋아하지 않았고, 그녀의 우두를 믿지 않았습니다. 부끄러운 시간은 저를 옳다고 증명했습니다.$B$B그녀를 쓰러뜨리는 것이 축복이지만 그녀의 야망의 반향은 빨리 사라지지 않을 것 같아 그녀의 의식의 결과는"}}
rows[1660062]={title={{18,181464085},"히르슈타의 에코"},description={{407,1115906359},"히르사투타가 풀어준 힘은 듀로타의 해안에서 떠다니는 항상 굶주린 나가의 눈길을 끌었다.$b$b고래와 뱀의 하이브리드들이 바다에서 빠져나와 해안 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동 동쪽 동쪽 동쪽 동쪽 동쪽 동쪽 동 동 동 동쪽 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동 동$b$b그들이 본 물결의 원인을 정확히 알고 있지 않을까 의심하지만, 그들은 그 본질을 조사하기 위해 왔어요.$b$b먼저 그들을 만나면 안 돼"},objectives={{51,1264748763},"듀로타 해안의 리벤루인 동굴에서 나가를 물리치"},completion={"<Though the old orc's eyes remain shut, he senses your presence all the same.>$B$BThe naga are dead.$B$BI felt it in the earth; it whispered every step you took into my ear. The water told me too, reddened by their blood.$B$BYou have my thanks, $C.","<오크의 눈이 닫혀있지만, 여전히 당신의 존재를 감지합니다.>$B$B나가들은 죽었어$B$B내가 지상에 느껴서, 네가 내 귀에 걸린 모든 걸음에도 속삭였다. 물도 내게 말했어요. 그들의 피로 빨라졌어요.$B$B고맙습니다 $C."},progress={{74,318882235},"<대장님께서는 눈을 감고 깊은 집중과 끝없는 인내심을 나타냅니다.>"}}
rows[1660063]={title={{16,270959558},"경매 과거"},description={{420,1137900263},"나가 때문에 왔어?$b$b완벽해$b$b보시다시피, 저는 동굴 유적들을 둘러보고, 경매에서 돌릴 수 있는 엘프 유물을 모았습니다. (그 유물들이 무엇을 가져왔는지 놀라실 겁니다.)$b$b제가  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ 을  ⁇ $b$b어쨌든 동굴로 가자니까, 몇 조각품을 가져오면 괜찮아?"},objectives={{70,1501075848},"리벤루인 동굴의 유적에서 고대 엘프 유적들을 복구 듀로타."},completion={{507,1012391453},"<고블린의 눈은 고슴도치 유물을 들고 있는 걸 보고 어린이가 과자를 들고 있는 것처럼 빛난다>$B$B멋지다, 멋지다, 놀라운 일이야$B$B이 문제를 해결해 줄게요 적어도 그는 숫자를 명명하기 전에 자르고$B$B좀 당황한 것 같네요, 이 상태는 끔찍해요.$B$B어쨌든, 약속을 지키지 않는다고 말할 수는 없어요."},progress={{35,1171457116},"우리가 얼마나 많은 돈을 벌 수 있는지 상상해 보세요!"}}
rows[1660064]={title={{22,1903359066},"듀로타의 '디어 건조'"},description={{351,597996772},"레이저힐에 새로 왔어?$b$b이 광산에서 일하는 기공들을 지휘하는 디르그란입니다.$b$b작은 동전을 벌고 싶니?$b$b저 병을 채우고 광산으로 가서 내 기공들의 목마구만 해소해야겠어$b$b듀로타은 물이 거의 없음을 알 수 있습니다. 하지만 마을 밖에서 몇 개의 수영장이 있습니다. 도로 옆, 여전히 마실 수 있습니다."},objectives={{103,991515236},"래저힐 바깥의 수영장에서 물을 채우고, 광산 기공들에게 술을 줘"},completion={{174,968753108},"어떻게 하는지 묻지 마, 하지만 내 말은 여기서보다 더 뜨겁다는 거야$B$B펭귄이 흔들리지 않는 하루도 지나지 않는다.$B$B그들이 가져온 차가운 물에 감사할 겁니다."},progress={{46,1365441945},"나도 차가운 물 한 잔이라도 마실 수 있어"}}
rows[1660065]={title={{12,488728385},"잠시 머물"},description={{156,1006869788},"앉으세요, 걱정 마세요, 우리 둘 다 있을 수 있어요.$b$b<오크가 환영하는 시음으로 자기 자신에게  ⁇ 어들었다는 것 같다>$b$b<아마도 공유할만한 게 있어요>"},objectives={{85,1072284167},"소음에서 잠시 떨어져 서둘러 바그말 스카이파프를 듣고 잠시 머물게 해"},completion={"Thank you for the company, $C.$B$BFew bother to listen to this old orc.","회사 주셔서 감사합니다 $C.$B$B이 늙은 오크를 듣는 데는 별로 신경쓰지 않는 사람이죠"}}
rows[1660066]={title={{20,123209862},"지평선 위로 솟는 연기"},description={{499,390145732},"이 벽 너머의 블러드하프 마을로 가는 거야?$b$b저는 그 지평선을 이렇게 지켜봤습니다. 바람은 연기를 들고 있었고,$b$b이상하지 않을 것입니다. 멀고어년]에도 타우렌들은 적 없이 살고 있습니다.$b$b메스카에 있는 암머스 그레이 아이에게 방문해 주세요. 그녀는 우리들 중 가장 현명하고 정상에서 유일하게 보호소를 돌보고 있습니다.$b$b보통 우리가 그녀의 집으로 가서 의식에 축복하는 물을 구합니다."},objectives={{62,1736302498},"아이리스 보호소 정상에서 애머스 그레이 아이와 이야기해"},completion={{253,16866496},"새로운 얼굴$B$B<장애인은 당신의  ⁇ 을 회색으로 털이 된 손으로  ⁇ 고 부드럽게 웃는다.>$B$B블러드하프 마을의 화재에 대해 왔어요?$B$B그는 듣지 않았다."}}
rows[1660067]={title={{23,384557639},"신성한 물 의 암포라"},description={{502,1055718068},"이 성원은 지구 어머니와 하늘 아버지를 기리기 위해 세워졌습니다. 비가 오면, 그 심장의 구멍이 난 돌은 구름이 너무 대대하게 주는 물을 모으고 있습니다.$b$b그럼, 모든 의식과 함께, 저는 그것을 축복합니다.$b$b토테마의 발을 씻는 물로 앰포라를 채우고 블러드하프 마을의 세지 무드렌에게 가져가라. 그 물로 그는 흥분된 요소들을 진정시키고 마을의 영적 조화를 회복할 수 있다.$b$b아드누노의 부발성을 치유할 수 있을지 모르겠지만, 그 효과를 완화시키는 데 도움이 될 것입니다."},objectives={{113,1897124632},"이리스 성원의 축복받은 물로 안포라를 채워서 블러드하프 마을의 세이즈 무드렌에게 가져와라"},completion={{354,369295251},"이건...$B$B<타우렌의 시선은 아머스 그레이 아이에서 축복받은 물의 양포를 보고 감사의 마음을 품고 있습니다.>$B$B이 물 이 주는 힘 을 느낄 수 있는가? 거의 없으니까요. 그것은 마치 영혼 을  ⁇ 는 것 처럼요. 긴, 험난한 하루 후 침묵.$B$B이 물들은 아드누노가 방해한 원자 균형을 회복하는데 도움이 될 것입니다."},progress={{65,73550575},"또 다른 젊은 타우렌이 있습니다. 이 마을은 유망한 전사들로 가득합니다."}}
rows[1660068]={title={{15,903073043},"에버스 들 의 추방"},description={{520,558132900},"아르두노는 불타게 된 샤만이었죠. 그는 자신의 어리석은 짓으로 죽었고, 다행히도 불꽃은 그의 집 너머로 퍼지지 않았습니다.$b$b하지만 그가 죽기 직전에 불러온 원자체는 여전히 화화한 유해들 사이에서 방황하고 있습니다.$b$b네 가지 요소 중 가장 휘발성이 강한 것$b$b이 물의 축복을 너희에게 주겠다. 그것을 사용하여 당신이 발견하는 불 원자들을 약화시키고 이 마을에서, 이 세상에서, 그들의 감옥계로 그들을 추방할 것이다."},objectives={{127,1897977033},"아드누노의 집 주변에서 돌아다니는 불의 원자들을 약화시키고 원자계로 다시 추방하도록 축복을 전달해"},completion={"The water’s blessing fades, but it has done its work.$B$BYou return unharmed.$B$BFew can say they’ve faced spirits of fire and lived to tell it.$B$BYou have done Bloodhoof Village a great service, $C.","물의 축복은 사라지고 있지만 그 일은 끝났어$B$B넌 무사히 돌아왔어$B$B소수의 사람들이 불의 영을 마주하고 살아서 그 이야기를 할 수 있다고 말할 수 있습니다.$B$B블러드하프 마을에 큰 봉사를 해줬어요 $C."},progress={{29,2107306227},"불꽃을 끄셨나요?"}}
rows[1660069]={title={{24,1179604036},"기억 하는 연기가"},description={"Young $R, my name is Emnil, ancestress of the Bloodhoof.$b$bI crossed the veil centuries ago, long before the children of my children laid claim to these lands. Then they brought my ashes and scattered them in this place; and they raised behind me the great totem you behold.$b$bArdunno, fiery of spirit, reckless, ever enamored of the flame, kept the ritual incense; but with his death the sacred smoke grows thin, and with it my bond to the realm of the living.$b$bWill you, out of honor, rekindle the fragrance and replenish the sacred incense?","젊은 $R, 내 이름은 에밀, 혈통의 조상.$b$b저는 수세기 전에 그 가면을 넘었고, 제 자녀들이 이 땅을 주장하기 훨씬 전에요. 그 후에 그들은 내 거품을 가져와서 이 곳에 흩어지게 했고,$b$b불타는 정신, 무분별, 항상 불에 매료, 의식 향기를 유지; 그러나 그의 죽음으로 신성한 연기가 희미하고, 그것은 살아있는 영역에 나의 유대.$b$b영광으로 향을 다시 불어넣고 성스러운 향기를 보충해 줄 수 있을까요?"},objectives={{86,1529335796},"에밀 원조의 제단에서 향수를 가져오세요."},completion={{194,2084883383},"향기가 다시 활력을 불어넣어 내 존엄성을 회복시켜준다$B$B내 자손의 자손들이 나의 축복을 더 받을 것이다. 날이 어두워질 때에 희망과 위로의 말씀을 가지고 있을 것이다."},progress={{61,50465088}," ⁇ 은 연기가 약해지면서 향기가 거의 소모되고..."}}
rows[1660070]={title={{12,488728385},"잠시 머물"},description={{160,314393140},"<타우렌 장로는 성원 지도자의 묘사에 부합합니다.$b$b<아마도 그녀가 당신과 공유할 가치가 있는 무언가를 가지고 있을지도 모른다.>"},objectives={{84,1093211902},"소음에서 잠시 떨어져 서둘러 잠시 동안 앰무스 그레이 아이를 들으세요."},completion={{231,1545177800},"여기 잠시 쉬고, 절벽 가장자리에 조용히, 때로는 말들은 진실을 다듬는 것 이상으로$B$B이 순간을 느껴라, 계속할 때까지 지켜라$B$B생명은 맛보아라. 육신과 말보다 더 강한 힘이다."}}
rows[1660071]={title={{14,219111472},"암울 한 경고"},description={{350,37959313},"잠깐만요$b$b또 다른 건 있습니다. <타리엘의 목소리가 강하고, 그의 입술에서 말들이 떨어집니다.>$b$b제 여동생을 유혹한 광신들은 뭔가 해야만 합니다$b$b난 올드라시લમાં 머물고 테나론 스톰그립에게 신조를 보고하고 넌 돌나어로 가서 타논카이 스위프트 루트에 모든 걸 말해$b$b둘 사이에, 그들은 이 일을 어떻게 막을 수 있는지 알 것입니다."},objectives={{43,1669900791},"톨론카이 스위프트 루트와 다라나르에서 이야기해"},completion={"Yes, $c? What business brings you to Dolanaar?$b$b<The druid gives your account his full attention. As your tale unfolds, his face darkens and the lines at the corners of his eyes deepen.>$b$bAegya… A name I'd hoped never to hear again. So they're here, then. In Teldrassil.$b$bThe audacity…$b$bForget the Cult, $n, and rest easy. I'll see to dismantling them myself.","- 그래 $c무슨 일이 도라나르로 데려왔어요?$b$b<드루이드는 당신의 이야기를 전폭적으로 다룬다. 당신의 이야기가 펼쳐지면서 그의 얼굴이 어두워지고 그의 눈의 모퉁이들의 선이 깊어진다.>$b$b에이그야, 다시는 듣지 않길 바랬던 이름이야$b$b용기...$b$b종파를 잊어라 $n안심하세요, 내가 직접 해체할게요"}}
rows[1660072]={title={{22,1949360278},"테렌 디온 의 도움"},description={{447,1753272173},"넌 여우 숭배를 살아남았어$b$b우리 위에 있는 절벽 위에 서 있는 테렌-디온 성원은 Sentinel들이 그들의 용기를 시험하는 곳이다.$b$b당신 같은 사람을 환영할 겁니다. 그 사람을 따라가게 해, 머리를 깨끗하게 해,$b$b그들을 싸우고, 그들의 리더인 애드릴리아 솔템퍼에게 보고해,"},objectives={{100,1686689766},"테렌 디온 성원에서 Sentinel와 이야기해 훈련에 도움을 주기 위해 그들을 듀얼에 도전해"},completion={{289,2100032901},"그래서, 여우 숭배...$b$b그녀의 눈은 깊은 기억의 우물이고, 그 아래에는 고대 분노가 발효됩니다.$b$b내가 내 경호를 준비해 줄게 될 거야 무관심이든 아니든 타논카이에서 그는 정치에서, 종교에서, 전쟁에서, 그리고 거의 모든 것에 중요한 것은 여성들이 명령을 내리는 것이다."},progress={"Yes, $c?","네, $c?"}}
rows[1660073]={title={{23,416678916},"발굴자 들 에게는 장소 가 없다"},description={{378,1706975615},"여우 숭배의 근접은 우리가 최근 직면한 문제를 설명합니다.$b$b대륙의 새들은 거의 안되죠 칼림도어 테일드라시일의 가지까지 도달하기 위해, 그러나 최근 수십 명이 이 성원을 둘러싼 바위에 정착했습니다.$b$b돌나아르로 돌아가기 전에 내 경호자들이 위협을 줄이고 독수리 알을 파괴하고 부모의 분노를 준비하라$b$b그럼 내게 보고해"},objectives={{68,1638537192},"도라나르 근처에 있는 테렌 디온 성원에 대해 고구려 달걀을 파괴해"},completion={{163,1141449239},"다 끝났어?$b$b내 세티니얼들은 나머지 사람들을 돌보고 새우 숭배의 둥지를 치고 레이디 에그야를 영원히 정의에 내놓을 준비가 돼 있을 거야"},progress={{33,640053013},"거북이를 다뤄봤어?"}}
rows[1660074]={title={{22,2004713197},"테일드라시લમાં 사는 지미"},description={"Ishnu-alah, $C.$b$bTeldrassil has grown dangerous of late, and Dolanaar is no exception.$b$bSouthwest of here, the earth yawns open to bare the vast heartwood of the World Tree's trunk. My sisters have found a termite colony there and are holding the line... but we're too few, and for every termite we kill, two more scuttle in to take its place.$b$bHelp us stem the termite threat, and I'll see you're rewarded in full for the risk you'll take down there.","이슈누알라 $C.$b$b테일드라실은 최근 위험해졌고, 도라나르도 예외는 아닙니다.$b$b남서쪽에서 지구가 열리고 있습니다. 세계 나무의 큰 나무를 벌려내기 위해. 내 자매들은 그곳에서 거북이 식민지를 발견하고 그 선을 지키고 있습니다. 하지만 우리는 너무 적고, 우리가 죽이는 거북이마다, 그 자리를 차지할 수 있는 더 많은 거북이 두 개 있습니다.$b$b ⁇ 어 위협을 막는 데 도움이 되세요. 그리고 저기에 걸린 위험을 보답받게 될 겁니다."},objectives={{88,1410305047},"돌나아르 근처에 있는 테일드라시일의 나무껍질에 들어가서 그 깊은 곳을 침식하는 뚜라미트를 물리치세요."},completion={"Well fought, $C.$B$BMy sisters acknowledge your merits with admiration… and a touch of envy.$B$BWe Sentinels will see to exterminating the rest.","잘 싸웠어 $C.$B$B내 자매들은 존경과 질투의 한 촉각으로 당신의 성과를 인정합니다.$B$B우린 세티니얼들이 나머지 사람들을 멸시할 거야"},progress={{67,1337056894}," ⁇ 미트를 마쳤어?"}}
rows[1660075]={title={{12,488728385},"잠시 머물"},description={{152,341252162},"<그녀를 바라보면, 테일드라실 자체가  ⁇ 는 불꽃으로 올라갈 수 있고, 앨렌나는 움직이지 않을 것이라고 확신합니다.>$b$b<아마도 그녀는 공유할 것이 있을지도 모른다>"},objectives={{89,1386434364},"소음에서 잠시 떨어져 서둘러 잠시 동안 알레나 위스퍼부그를 들으세요."},completion={{122,692415482},"<알레나의 시선은 어두워집니다. 돌나아르의 아름다움은 그 종파의 이름에 의해 유령된 공포를 쫓아낼 만큼 충분하지 않습니다.>"}}
rows[1660076]={title={{18,892093046},"성장 하는 사업"},description={"<The dwarf waves from afar to catch your eye; big sweeping arms at first, then he starts hopping in place.>$b$bWell met! <pants> I saw how you handled Groldha. I'm guessing you won't be lingering in Anvilmar much longer...$b$bIf that's the case and your feet carry you to Kharanos, I've a message that needs delivering.$b$bFind Eyma at the inn and tell her the talks in Anvilmar bore fruit. They want a shipment of our best ale; if it wins them over, we've got ourselves regular buyers. The ancestors smile on us, $C!","<왜란은 멀리서 파동하여 눈길을 끌고 있습니다. 처음에는 큰 팔을 닦고, 그 다음 그는 자신의 위치에 뛰어 시작합니다.>$b$b그롤다를 어떻게 처리했는지 봤는데 더 오래 안빌마르에 머물지 않을거라고 생각하네$b$b만약 네 발이 널 카라노스로 데려다주면, 전 전달해야 할 메시지가 있어.$b$b에이마를 숙소에서 찾아서 애니빌마르에서의 대화가 ಫಲ적이라고 말해줘 $C!"},objectives={{70,731780110}," ⁇ 라노스의  ⁇ 더브루 디스틸리에서 아이마 썬더브루와 이야기해"},completion={{220,1285671519},"노리와 그가 전달해 줄 메시지를 언급하면 왜니의 호기심이 부드러울 겁니다.$B$B좋은 소식입니다. 그녀는 \"많은 열정을 가지고 있지 않습니다\".라고 말합니다.$B$B최대한 빨리 배송이 준비될 수 있도록 하겠습니다."}}
rows[1660077]={title={{17,1063013575},"썬더브레의 홉"},description={{402,1978072607},"노리는 네 안에 뭔가 보셨어$b$b여기 있는 거 때문에, 좀 도와줄 수 있겠죠.$b$b숙소 밖으로 나와 왼쪽으로 보시면 디스틸리아의 호프 정원을 볼 수 있습니다.$b$b오늘 고객들이 많이 많아요,  ⁇ 을  ⁇ 고 내게 가져오시면 안 돼요?"},objectives={{83,188348382},"카라노스의 썬더브루 양조장 부지에서 썬더브루 홉 일곱 개를 거두십시오."},completion={{207,625011854},"에이마는 네가 모은 호프의 향을 흡입하고 눈은  ⁇ 어 닫는다$B$B술에 취하는 것$B$B야생동물들이 너무 슬퍼하지 않았으면 좋겠다."},progress={{13,1728746028}," ⁇ 이 있잖아?"}}
rows[1660078]={title={{14,1517748981},"보트들이 파업"},description={{584,413525142},"조심해 터널은 며칠 동안 통과되지 않았습니다$b$b내 발명품, 내가 이 손으로 만든 자동화, 더 코믹한 것보다 비극적인,$b$b이제 그들은 가까이 떠돌아다니는 모든 것을 공격합니다. 그들은 이미 생명을 주장하고, 더 나쁜 것은, 그들은 내 명성을 망치고 있습니다!$b$b터널에 들어가면 안 돼$b$b다른 사람들처럼 아냐, 내가 널 보고 있어, 넌 그냥 살아남을 수 있어, 그들을 파괴해..."},objectives={{117,1559030539},"통제 불가능한 자동기를 물리치고, 카라노스 터널을 막고, 그 유해에서 재사용 가능한 기계 부품을 복구한다."},completion={{396,1744369093},"살아 돌아왔군요!$B$B회수한 부품도 적지 않고요.$B$B<이코라스가 기침을 하며 동굴 입구에서 피어오르는 가는 연기를 손으로 내젓고 안절부절못한다.>$B$B이 부품에다 양조장에서 독한 술 몇 잔만 걸치면, 다음 작업에 뛰어들 영감과 배짱이 살아날 것 같네요. 첫 작품들보다 튼튼하고 말도 잘 듣는 차세대 자동인형을 만드는 겁니다.$B$B고마워요!"},progress={{24,1610257848},"어떻게 지내세요?"}}
rows[1660079]={title={{14,1239909864},"라이브 파이어 데모"},description={{347,1002185357},"<왜란자는 무릎 사이에 둥지를 틀고 바퀴를  ⁇ 다.  ⁇ ,  ⁇ ,  ⁇ ,  ⁇ ,  ⁇ ,  ⁇ ,  ⁇ ,  ⁇ ,  ⁇ ,  ⁇ ,  ⁇ ,  ⁇ ,  ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ , ⁇ ,$b$b미안해, 관객이 있다는 걸 알아차리지 않았어.$b$b몇 가지 공을 내놓으면 좋겠나? 목표물은 항상 납에 굶주리고, 운이 좋으면 구매자의 눈을 잡을 수 있을 것이다.$b$b이 탄약은 팔리지 않을 거야"},objectives={{91,1811965663},"고르나르의 블러더버스와 탄약을 시험해 보아라"},completion={{201,410860093},"엄마의  ⁇ 에 맹세해!$B$B네 눈으로 봤어?$B$B제발 이 일을 널리 알리세요."},progress={{45,1322869416},"목표에 대해 걱정하지 마, 잘 날려줘!"}}
rows[1660080]={title={{12,488728385},"잠시 머물"},description={{209,1391482564},"< 무덤 을 파는 사람 의 피곤 한 모습 은  ⁇  에서 긴 하루 를 묘사 합니다. 그 구멍 은 깊이 로만 인상적 이 아니라 흙 벽 의 깨끗 하고 닦아진 완성 으로만 인상적 이 됩니다.>$b$b<아마도 공유할만한 게 있어요>"},objectives={{88,1480416913},"소음에서 잠시 떨어져 서둘러 잠시 동안 무덤을 파는 사람이 아닌 것을 듣도록 기다려라"},completion={"Choose your enemies with care, $C.$B$BPlenty of dwarves pass through Kharanos eager to forge a legend… only to end up dropped into one of these niches.","적들을 조심스럽게 선택하라 $C.$B$B많은 왜들이 한라노스를 지나가며 전설을 만들고 싶어서 결국 이런 틈새에 빠지게 됩니다."}}
rows[1660081]={title={{21,691393407},"고백자 를 판단 하는 것"},description={{352,1822684920},"내가 고백할 게 없어 왜 계속 날 때려나?$b$b또 다른 고통스러운 외침, 긴 침묵이 이어집니다. 마침내, 그는 당신의 존재를 등록하는 것처럼 보입니다.$b$b고백자, 죽여라, 더 이상 견딜 수 없어 그는 고문자 살인자, 괴물보다 더 나쁜 괴물$b$b평화를 줘서 그를 없애라"},objectives={{57,1189560698},"심사위원 콘라드 신성 신사를 죽여라"}}
rows[1660082]={title={{18,1095089311},"우리 모두 에 어떤 평준 이 있습니까?"},description={{410,832580471},"제발, 제발...$b$b<영령은 그의 숨을  ⁇ 고, 그가 교회의 포로였던 시절의 기억에 사라져요>$b$b<이 곳은 저주받은 곳이고, 그 유령들은 지금 이 곳에 갇혀있어요.$b$b그만, 그만, 그만$b$b<저 감옥을 깨끗하게 하고 그 홀에서 떠다니는 모든 생물, 귀신이든 아니든,"},objectives={{81,1030705041},"불사한 놈들을 죽여라."}}
rows[1660083]={title={{28,636533546},"죽음 의 로아 의 의원"},description={{329,198153990},"대 우프스타트 3는 우리가 생각했던 것보다 더 세련된 놈들이었다$b$b내 마스터 Bwonsamdi '죽은 자'가 증오, 그리고 바로 그 이유 때문에 그들은 그들의 킴릭 강아지 보호 할 세운.$b$bVol'zeen 그의 이름, 끔찍한 트롤, 피 미친 Berserker, dey '그를 호출 할 것.$b$b내 마조는 그런 일에 대해 쓸모없어"},objectives={{60,770300070},"비참한 죽은 트롤인 볼진을 물리치세요"}}
rows[1660084]={title={{17,1994432210},"악성 가족"},description={{427,1172047722},"히르슈타의 의식이 망쳤지만, 그녀가 불려온 존재는$b$b괴상한 기메라가 될 거야$b$b히어'이크, 다ంబ라, 그리고 샤드라가 이 길을 타면으로 침투했다. 어떻게든, 나는 그 생명은 거미, 뱀, 박쥐의 영혼과 연결된 것 같다.$b$b모두 죽여라$b$b내 주왕 부원삼디는 너그러운 사람이 될 것입니다."},objectives={{88,1795774188},"타면으로 가는 길에서 박쥐, 거미, 비거를 물리치면 정상적인 어려움에 처해 있을 것이다."}}
rows[1660085]={title={{17,2109446084},"엘리드나의 유산"},description={{406,481712905},"우리 제안 을 생각 하면서, 큰 여우 는 둥지를 먹이를 가져오는 사람 들 을 보상 하는 것 을 기억 하십시오. 따라서, 일리드나 에게 일생 에 있던 재산 은 이제 그 를 빼앗은 사람 에게 새로운 주인 을 찾습니다.$b$b<엘프의 날카로운 손, 그녀의 친척보다 새우의 발톱처럼, 당신의 손잡고 손바닥에 장식된 pendant을 넣어>$b$b엘라드나의 물건 중 하나, 그 pendant, 원하는 대로 해"},objectives={{83,323041975},"타릴 윈스트록과 얘기해 동생 엘리드나의 수리를 넘겨줘"},completion={{332,797802693},"<손을 열고 엘리드나의 수직을 드러내다. <그것을 보고, 타릴의 슬픔에 사로잡힌 표정은 아주 조금 쉬어진다.>$b$b유감할 수 있는 시체가 없다면, 이것만 해야 할 것 같아요.$b$b<그분은 떨고 있는 손으로 수단을 잡고 가슴에 누릅니다.>$b$b엘리드나... 무슨 광기가 널 이 퇴행자들한테 데려갔어?"},progress={{44,1464271182},"<엘프의 눈은 걱정으로 흐려져 있습니다.>"}}
rows[1660088]={title={{21,68805526},"인키시션 의 유물장"},description={{532,1876989906},"뭔가 잘못됐어, 정말 잘못됐어$b$b<Clara the Mad wrings her clammy hands in a nervous frenzy.> <클라라 더 매드, 그녀의  ⁇ 한 손을 긴장한 광기 속에서 굽히고 있습니다.>$b$b문이 다시 열렸어요. 봉기는 깨졌어요. 내 여동생들이 있었을까요? 불가능해요. 저는 다시 북녘골로 돌아갈 수 없습니다.$b$b<클라라 미쳤던 눈빛이 너를 뚫고, 야생, 열병한 사람>$b$b네가 해! 목소리 침묵! 내가 가진 작은 것을 너에게 줄게! 그들은 거짓말을 했다:  ⁇ 빛 우리를 보호할 것이다, 그들은 말했다. 하! 이제 그들은 모두 죽었습니다. 그들 모두! 그녀 외에는. 그녀 외에는!$b$b<클라라는 눈이 공허로 흘러내리기 전에 스스로 웃는다.>"},objectives={{153,233976546},"모험가 다섯 명으로 파티를 구성하여 위험한 이단심문의 금고로 내려가십시오. 일반 난이도에서 기만자의 현신을 물리치십시오."}}
rows[1903512]={title={{42,56551042},"승천의 길: 모금 및 자본"},description={{141,40567515},"문자를 진행하여 열고, \"무엇이 아닌 것\" 탭을 클릭하십시오.\010'돌아가는 것' 또는 '알은 것'을 필터링하여 검색하고, 스크롤을 클릭하고, '공급 항목'을 클릭하십시오."},objectives={{141,40567515},"문자를 진행하여 열고, \"무엇이 아닌 것\" 탭을 클릭하십시오.\010'돌아가는 것' 또는 '알은 것'을 필터링하여 검색하고, 스크롤을 클릭하고, '공급 항목'을 클릭하십시오."}}
rows[1903513]={title={{44,946657505},"승천의 길: 미스틱 스크롤을 활성화"},description={{544,853399790},"미스틱 매혹적인 스크롤은 전세계에 숨겨진 적들을 물리치고, 다른 플레이어들을 거래함으로써 얻을 수 있습니다.    일단 얻으면 미스터 매혹적인 제단을 방문하여 미스터 스크롤을 적용하여 그 힘을 얻으십시오! 신비로운 마법의 제단이 수도권에서 종종 발견될 수 있습니다. 또는 당신은 세계를 방문하기 위해 모험을 할 수 있습니다. 세계 지도에 그 위치가 표시되어 있습니다.    미스틱 인잔트는 영웅으로서의 힘을 풀어주는 열쇠입니다. 마력을 부여하는 미스틱 매춘자를 찾아내거나 새로운 아케티프를 열고 힘을 높여라"},objectives={{266,1866479211},"- 적을 물리치고 다른 플레이어를 거래함으로써 미스틱 매춘 스롤을 획득하세요. - 수도권이나 세계에서 발견된 미스틱 매춘 제물과 상호작용하고 인천 매춘 스롤 탭을 선택하세요. - 미스틱 스롤을 활성화하고 액티브 인천 슬롯에 적용하세요."}}
rows[1903520]={title={{38,1581244289},"승천의 길: 마법의 순위를"},description={{82,1137743048},"초보자의 상승책에 대해 이야기해\010\"내 훈련\"을 선택하고 주문을 순서대로 나열해 보세요."},objectives={{82,1137743048},"초보자의 상승책에 대해 이야기해\010\"내 훈련\"을 선택하고 주문을 순서대로 나열해 보세요."}}
rows[1903521]={title={{40,1199905229},"승천의 길: 호드의 수도로!"},description={{45,206139002},"오그리마 로프하우 로드 사우르펀에게 말해주세요"},objectives={{45,206139002},"오그리마 로프하우 로드 사우르펀에게 말해주세요"}}
rows[1903522]={title={{43,246325044},"승천의 길: 얼라이언스의 수도로!"},description={{39,1950615372},"스톰윈드 스티파니 터너와 이야기해"},objectives={{39,1950615372},"스톰윈드 스티파니 터너와 이야기해"}}
rows[1903539]={title={{46,563911399},"승천의 길: 당신의 수업 환상을 구축"},description={{792,1306530417},"N을 누르거나 미니맵 옆에 있는 스크롤 아이콘을 클릭하면 캐릭터 진출 메뉴가 열립니다.  메뉴의 왼쪽 아래쪽에 있는 히어로 아키텍트 탭을 클릭하세요.  오른쪽 목록의 다양한 빌드들을 스크롤하여 흥미를 느끼는 또는 당신의 수업 환상에 맞는 하나를 찾으십시오. 언제든 기계를 바꿀 수 있어 재미있게 즐기며 눈에 띄는 것을 선택해 보세요. 만약 그 빌드 방식이 당신의 플레이 스타일에 맞지 않는다면 항상 재작업할 수 있습니다.  재생하고 싶은 빌드를 찾아서 \"이 빌드를 선택하세요\"를 선택하여 활성화합니다. 당신은 즉시 필요한 모든 마법과 재능을 배울 것입니다. 그리고 당신은 자동으로 마법과 재능을 배울 것입니다!  만약 여러분이 승천에 대해 경험이 있거나 처음부터 여러분의 기획을 만들고 싶다면 \"아니, 저는 스스로 능력과 재능을 선택하고 싶습니다\"."},objectives={{70,1604315984},"영웅 아키텍트에서 특징적인 레벨 빌드를 선택하거나 자신만의 빌드를 만들 수 있습니다."}}
