rows[4420430]={title={{31,179797563},"승천의 길: 초보자"},description={{154,973676372},"라이딩 트레이너와 이야기해 Novice Riding를 배우자\010여행자 트레이너에서 첫 마운트를 가져오세요\010가방만 열고 새 마운트를 오른쪽으로 클릭하세요."},objectives={{154,973676372},"라이딩 트레이너와 이야기해 Novice Riding를 배우자\010여행자 트레이너에서 첫 마운트를 가져오세요\010가방만 열고 새 마운트를 오른쪽으로 클릭하세요."},completion={"Here is your first mount, $N. Ride well.","여기 첫 마운틴이 있습니다 $N잘 타세요"},progress={"Have you learned to ride yet, $N?","이제까지 운전을 배웠어 $N?"}}
